// mncs.family.rfc_status.v1 — the MNCS-native decision core for RFC status claims.
//
// A status string alone can never upgrade an RFC: every implementation claim
// passes through these gates with its criterion tally and evidence flag.
// Downgrades are always allowed; upgrades require a PASS gate. This keeps the
// machine-readable ledger (rfcs/conformance-ledger.json) honest by executing
// its transition rules instead of trusting editor discipline.
//
// Dominance discipline is inherited from mncs.core.status: gates weaken
// claims monotonically and never map UNKNOWN to PASS.
module mncs.family.rfc_status.v1;

use mncs.core.status.v1 as status;

enum DesignState { Draft, Proposed, Accepted, Stable, Superseded }

enum ImplState { Absent, Substrate, Partial, Bounded, Experimental, Complete }

record CriterionTally { required: i64, satisfied: i64, partial: i64, excused: i64, evidence_ok: bool }

fn rank(state: ImplState) -> (result: i64) {
    return match state {
        Absent => 0,
        Substrate => 1,
        Partial => 2,
        Bounded => 3,
        Experimental => 4,
        Complete => 5,
    };
}

// EXPERIMENTAL gate: every required criterion is satisfied, partial, or
// explicitly excused with a recorded gap; at least one is fully satisfied;
// and every non-excused claim carries qualifying evidence. Anything less
// stays UNKNOWN or FAIL.
fn gate_experimental(tally: CriterionTally) -> (result: status.Status) {
    if tally.required <= 0 {
        return status.Status.UNKNOWN;
    }
    let accounted: i64 = tally.satisfied +% tally.partial +% tally.excused;
    if tally.satisfied < 0 || tally.partial < 0 || tally.excused < 0 || accounted > tally.required {
        return status.Status.FAIL;
    }
    if tally.evidence_ok {
        if tally.satisfied > 0 && accounted == tally.required {
            return status.Status.PASS;
        }
        return status.Status.UNKNOWN;
    }
    return status.Status.FAIL;
}

// IMPLEMENTED gate: strictly stronger. Every required criterion is fully
// satisfied with evidence; partial credit and excuses are not enough for a
// complete claim.
fn gate_implemented(tally: CriterionTally) -> (result: status.Status) {
    if tally.required <= 0 {
        return status.Status.UNKNOWN;
    }
    let accounted: i64 = tally.satisfied +% tally.partial +% tally.excused;
    if tally.satisfied < 0 || tally.partial < 0 || tally.excused < 0 || accounted > tally.required {
        return status.Status.FAIL;
    }
    if tally.evidence_ok {
        if tally.partial == 0 && tally.excused == 0 && tally.satisfied == tally.required {
            return status.Status.PASS;
        }
        return status.Status.UNKNOWN;
    }
    return status.Status.FAIL;
}

// Status transitions: staying put and honest downgrades always pass; any
// upgrade requires the supplied gate verdict to be PASS.
fn transition_allowed(from: ImplState, to: ImplState, gate: status.Status) -> (result: bool) {
    if rank(to) <= rank(from) {
        return true;
    }
    return match gate {
        PASS => true,
        FAIL => false,
        UNKNOWN => false,
    };
}

// The RFC 0007 tranche tally, executable form: 20 required criteria,
// 18 satisfied, 1 partial (heterogeneous Fabric workers, 0007-C16),
// 1 excused (erasure, recorded gap 0007-G6), evidence bound. The gate must
// stay PASS for the BOUNDED_IMPLEMENTATION claim and must refuse IMPLEMENTED.
fn rfc0007_tally() -> (result: CriterionTally) {
    return CriterionTally { required: 20, satisfied: 18, partial: 1, excused: 1, evidence_ok: true };
}

// Corpus entrypoints: zero-argument wrappers so experiment cases can invoke
// the ledger's own tally without supplying arguments.
fn check_rfc0007_experimental() -> (result: status.Status) {
    return gate_experimental(rfc0007_tally());
}

fn check_rfc0007_implemented() -> (result: status.Status) {
    return gate_implemented(rfc0007_tally());
}

mncs 0.13;

// mncs.jit.binding — logical bindings and generational publication
// for the MNCS-native JIT orchestration layer.
//
// A Binding selects at most one Executable per logical definition.
// Publication is generational and atomic at the value level: `define`
// (in `mncs.jit.session.v1`) moves the current selection into
// previous_* and parks the binding Stale with no artifact;
// `note_compiled` records a provider compilation as a Compiled
// artifact; `publish` validates the artifact and swings the binding
// to it in one total step. A failed generation therefore CANNOT
// replace the active binding: until `publish` accepts, the previous
// selection stays intact in previous_*, and `abandon` restores it.
//
// PUBLISH POLICY (`publish` reasons):
//   0 ok,
//   1 rejected-closed, 2 rejected-unknown-artifact,
//   3 rejected-wrong-owner-or-generation (the artifact names a
//     different logical definition or a superseded generation),
//   4 rejected-bad-lifecycle (only Compiled or Published artifacts
//     activate; Active republication is a new generation, and
//     Retired artifacts never reactivate),
//   5 rejected-stale-proof (the artifact triple or its definition
//     triple no longer matches the session era).
// Every rejection returns the session unchanged.
// NOTE-COMPILED POLICY (`note_compiled` reasons):
//   0 ok,
//   1 rejected-closed, 2 rejected-artifacts-full,
//   3 rejected-unknown-logical, 4 rejected-unknown-provider,
//   5 rejected-stale-generation (only the latest source generation
//     of a logical definition may gain executables),
//   6 rejected-unimplemented-provider (recording an LLVM/Native
//     compile would fake execution that never happened).
//
// SUPERSESSION: publishing a new artifact for a logical definition
// demotes the previously Active artifact for that definition to
// Published: still alive and directly invocable while referenced,
// serving no new calls through bindings. Retirement (`retire_
// artifact`) moves a live artifact to Retired and marks bindings
// that selected it Stale (reason 4); resolve then refuses them.
//
// RESOLVE POLICY: `resolve` reports the binding honestly — found,
// generation, artifact, state — plus `proof_current` (the selected
// generation's definition era still matches the session era). The
// driver invokes only Valid + proof-current selections; anything
// else falls back, recompiles, or retires through these same entry
// points.
//
// Complexity bounds: every scan is over the 8/16-slot windows;
// publish touches at most one extra artifact row. No operation
// allocates; every function is total.
module mncs.jit.binding.v1;

use mncs.core.logic.v1 as logic;
use mncs.jit.lifecycle.v1 as lifecycle;
use mncs.jit.proof.v1 as proof;
use mncs.jit.session.v1 as session;
use mncs.jit.types.v1 as types;

record NoteOut {
    session: types.Session,
    artifact_code: u64,
    accepted: bool,
    reason: u64,
}

record PublishOut {
    session: types.Session,
    accepted: bool,
    reason: u64,
}

record AbandonOut {
    session: types.Session,
    restored: bool,
}

record RetireArtifactOut {
    session: types.Session,
    retired: bool,
}

record ResolveOut {
    found: bool,
    generation: u64,
    artifact: u64,
    state_code: u64,
    proof_current: bool,
}

// --- Window scans (single level projections only) ---

fn binding_slot(session: types.Session, logical: u64) -> (result: u64) {
    let binds: [types.Binding; 8] = session.bindings;
    iterate i over binds carrying slot: u64 = session.binding_count {
        let hit: bool = i < session.binding_count && binds[i].logical == logical;
        next slot = select(hit, i, slot);
    }
    return slot;
}

fn artifact_slot(session: types.Session, code: u64) -> (result: u64) {
    let arts: [types.Executable; 16] = session.artifacts;
    iterate i over arts carrying slot: u64 = session.artifact_count {
        let hit: bool = i < session.artifact_count && arts[i].code == code;
        next slot = select(hit, i, slot);
    }
    return slot;
}

fn latest_generation(session: types.Session, logical: u64) -> (result: u64) {
    let rows: [types.Definition; 8] = session.defs;
    iterate i over rows carrying gen: u64 = 0 {
        let hit: bool = i < session.def_count && rows[i].logical == logical;
        next gen = select(hit, rows[i].generation, gen);
    }
    return gen;
}

fn def_slot(session: types.Session, logical: u64, generation: u64) -> (result: u64) {
    let rows: [types.Definition; 8] = session.defs;
    iterate i over rows carrying slot: u64 = session.def_count {
        let hit: bool = i < session.def_count && rows[i].logical == logical && rows[i].generation == generation;
        next slot = select(hit, i, slot);
    }
    return slot;
}

// --- Record a provider compilation ---

fn note_compiled(session: types.Session, logical: u64, generation: u64, provider_code: u64, compile_ms: u64, sem: u64, proof_gen: u64, bits: u64) -> (result: NoteOut) {
    if session.closed {
        return NoteOut { session: session, artifact_code: 0, accepted: false, reason: 1 };
    } else {
    }
    if logic.bool_not(types.provider_is_known(provider_code)) {
        return NoteOut { session: session, artifact_code: 0, accepted: false, reason: 4 };
    } else {
    }
    if logic.bool_not(types.provider_is_implemented(provider_code)) {
        return NoteOut { session: session, artifact_code: 0, accepted: false, reason: 6 };
    } else {
    }
    let bslot: u64 = binding_slot(session, logical);
    if bslot >= session.binding_count {
        return NoteOut { session: session, artifact_code: 0, accepted: false, reason: 3 };
    } else {
    }
    if generation != latest_generation(session, logical) {
        return NoteOut { session: session, artifact_code: 0, accepted: false, reason: 5 };
    } else {
    }
    if session.artifact_count >= 16 {
        return NoteOut { session: session, artifact_code: 0, accepted: false, reason: 2 };
    } else {
    }
    let code: u64 = session.next_artifact;
    let art: types.Executable = types.Executable {
        code: code,
        logical: logical,
        generation: generation,
        provider_code: provider_code,
        lifecycle_code: 1,
        semantic_generation: sem,
        proof_generation: proof_gen,
        assumption_bits: bits,
        compile_ms: compile_ms,
        publish_seq: 0,
    };
    let done: types.Session = types.Session {
        semantic_generation: session.semantic_generation,
        proof_generation: session.proof_generation,
        next_logical: session.next_logical,
        next_generation: session.next_generation,
        next_artifact: session.next_artifact +% 1,
        publish_seq: session.publish_seq,
        closed: session.closed,
        defs: session.defs,
        def_count: session.def_count,
        bindings: session.bindings,
        binding_count: session.binding_count,
        artifacts: replace(session.artifacts, session.artifact_count, art),
        artifact_count: session.artifact_count +% 1,
        edges: session.edges,
        edge_count: session.edge_count,
    };
    return NoteOut { session: done, artifact_code: code, accepted: true, reason: 0 };
}

// --- Publish (atomic binding swing) ---

record PublishScan {
    artifacts: [types.Executable; 16],
}

fn publish(session: types.Session, logical: u64, artifact_code: u64) -> (result: PublishOut) {
    if session.closed {
        return PublishOut { session: session, accepted: false, reason: 1 };
    } else {
    }
    let aslot: u64 = artifact_slot(session, artifact_code);
    if aslot >= session.artifact_count {
        return PublishOut { session: session, accepted: false, reason: 2 };
    } else {
    }
    let arts: [types.Executable; 16] = session.artifacts;
    let art: types.Executable = arts[aslot];
    if art.logical != logical {
        return PublishOut { session: session, accepted: false, reason: 3 };
    } else {
    }
    if art.generation != latest_generation(session, logical) {
        return PublishOut { session: session, accepted: false, reason: 3 };
    } else {
    }
    if logic.bool_not(art.lifecycle_code == 1 || art.lifecycle_code == 2) {
        return PublishOut { session: session, accepted: false, reason: 4 };
    } else {
    }
    let dslot: u64 = def_slot(session, logical, art.generation);
    if dslot >= session.def_count {
        return PublishOut { session: session, accepted: false, reason: 3 };
    } else {
    }
    let rows: [types.Definition; 8] = session.defs;
    let def: types.Definition = rows[dslot];
    let era_ok: bool = proof.artifact_proof_valid(art.semantic_generation, art.proof_generation, art.assumption_bits, session.semantic_generation, session.proof_generation, def.assumption_bits)
        && proof.proof_current(def.semantic_generation, def.proof_generation, session.semantic_generation, session.proof_generation);
    if logic.bool_not(era_ok) {
        return PublishOut { session: session, accepted: false, reason: 5 };
    } else {
    }
    let seq: u64 = session.publish_seq +% 1;
    let seed: PublishScan = PublishScan { artifacts: session.artifacts };
    iterate i over arts carrying fold: PublishScan = seed {
        let live: bool = i < session.artifact_count;
        let cur: types.Executable = fold.artifacts[i];
        let supersede: bool = live && cur.logical == logical && cur.lifecycle_code == 3 && cur.code != artifact_code;
        let activate: bool = live && i == aslot;
        let next_code: u64 = select(activate, 3, select(supersede, 2, cur.lifecycle_code));
        let next_seq: u64 = select(activate, seq, cur.publish_seq);
        let stepped: types.Executable = types.Executable {
            code: cur.code,
            logical: cur.logical,
            generation: cur.generation,
            provider_code: cur.provider_code,
            lifecycle_code: next_code,
            semantic_generation: cur.semantic_generation,
            proof_generation: cur.proof_generation,
            assumption_bits: cur.assumption_bits,
            compile_ms: cur.compile_ms,
            publish_seq: next_seq,
        };
        next fold = PublishScan { artifacts: replace(fold.artifacts, i, stepped) };
    }
    let bslot: u64 = binding_slot(session, logical);
    if bslot >= session.binding_count {
        return PublishOut { session: session, accepted: false, reason: 3 };
    } else {
    }
    let binds: [types.Binding; 8] = session.bindings;
    let cur_b: types.Binding = binds[bslot];
    let swung: types.Binding = types.Binding {
        logical: logical,
        generation: art.generation,
        artifact: artifact_code,
        previous_generation: cur_b.previous_generation,
        previous_artifact: cur_b.previous_artifact,
        state_code: 0,
        stale_reason: 0,
    };
    let done: types.Session = types.Session {
        semantic_generation: session.semantic_generation,
        proof_generation: session.proof_generation,
        next_logical: session.next_logical,
        next_generation: session.next_generation,
        next_artifact: session.next_artifact,
        publish_seq: seq,
        closed: session.closed,
        defs: session.defs,
        def_count: session.def_count,
        bindings: replace(binds, bslot, swung),
        binding_count: session.binding_count,
        artifacts: fold.artifacts,
        artifact_count: session.artifact_count,
        edges: session.edges,
        edge_count: session.edge_count,
    };
    return PublishOut { session: done, accepted: true, reason: 0 };
}

// --- Abandon (explicit rollback to the previous selection) ---

fn abandon(session: types.Session, logical: u64) -> (result: AbandonOut) {
    let bslot: u64 = binding_slot(session, logical);
    if bslot >= session.binding_count {
        return AbandonOut { session: session, restored: false };
    } else {
    }
    let binds: [types.Binding; 8] = session.bindings;
    let cur: types.Binding = binds[bslot];
    let can: bool = cur.state_code == 1 && cur.previous_generation != 0;
    if logic.bool_not(can) {
        return AbandonOut { session: session, restored: false };
    } else {
    }
    let back: types.Binding = types.Binding {
        logical: logical,
        generation: cur.previous_generation,
        artifact: cur.previous_artifact,
        previous_generation: 0,
        previous_artifact: 0,
        state_code: 0,
        stale_reason: 0,
    };
    let done: types.Session = types.Session {
        semantic_generation: session.semantic_generation,
        proof_generation: session.proof_generation,
        next_logical: session.next_logical,
        next_generation: session.next_generation,
        next_artifact: session.next_artifact,
        publish_seq: session.publish_seq,
        closed: session.closed,
        defs: session.defs,
        def_count: session.def_count,
        bindings: replace(binds, bslot, back),
        binding_count: session.binding_count,
        artifacts: session.artifacts,
        artifact_count: session.artifact_count,
        edges: session.edges,
        edge_count: session.edge_count,
    };
    return AbandonOut { session: done, restored: true };
}

// --- Retire one artifact ---

record RetireBindFold {
    bindings: [types.Binding; 8],
}

fn retire_artifact(session: types.Session, code: u64) -> (result: RetireArtifactOut) {
    let aslot: u64 = artifact_slot(session, code);
    if aslot >= session.artifact_count {
        return RetireArtifactOut { session: session, retired: false };
    } else {
    }
    let arts: [types.Executable; 16] = session.artifacts;
    let art: types.Executable = arts[aslot];
    if logic.bool_not(lifecycle.transition_allowed(art.lifecycle_code, 4)) {
        return RetireArtifactOut { session: session, retired: false };
    } else {
    }
    let dead: types.Executable = types.Executable {
        code: art.code,
        logical: art.logical,
        generation: art.generation,
        provider_code: art.provider_code,
        lifecycle_code: 4,
        semantic_generation: art.semantic_generation,
        proof_generation: art.proof_generation,
        assumption_bits: art.assumption_bits,
        compile_ms: art.compile_ms,
        publish_seq: art.publish_seq,
    };
    let retired_window: [types.Executable; 16] = replace(arts, aslot, dead);
    let binds: [types.Binding; 8] = session.bindings;
    let bseed: RetireBindFold = RetireBindFold { bindings: binds };
    iterate j over binds carrying bfold: RetireBindFold = bseed {
        let live: bool = j < session.binding_count;
        let b: types.Binding = bfold.bindings[j];
        let hit: bool = live && b.artifact == code && b.state_code == 0;
        let marked: types.Binding = types.Binding {
            logical: b.logical,
            generation: b.generation,
            artifact: b.artifact,
            previous_generation: b.previous_generation,
            previous_artifact: b.previous_artifact,
            state_code: select(hit, 1, b.state_code),
            stale_reason: select(hit, 4, b.stale_reason),
        };
        next bfold = RetireBindFold { bindings: replace(bfold.bindings, j, marked) };
    }
    let done: types.Session = types.Session {
        semantic_generation: session.semantic_generation,
        proof_generation: session.proof_generation,
        next_logical: session.next_logical,
        next_generation: session.next_generation,
        next_artifact: session.next_artifact,
        publish_seq: session.publish_seq,
        closed: session.closed,
        defs: session.defs,
        def_count: session.def_count,
        bindings: bfold.bindings,
        binding_count: session.binding_count,
        artifacts: retired_window,
        artifact_count: session.artifact_count,
        edges: session.edges,
        edge_count: session.edge_count,
    };
    return RetireArtifactOut { session: done, retired: true };
}

// --- Resolve ---

fn resolve(session: types.Session, logical: u64) -> (result: ResolveOut) {
    let bslot: u64 = binding_slot(session, logical);
    let found: bool = bslot < session.binding_count;
    let binds: [types.Binding; 8] = session.bindings;
    let b: types.Binding = binds[select(found, bslot, 0)];
    let dslot: u64 = def_slot(session, logical, b.generation);
    let rows: [types.Definition; 8] = session.defs;
    let row: types.Definition = rows[select(dslot < session.def_count, dslot, 0)];
    let current: bool = found && dslot < session.def_count && proof.proof_current(row.semantic_generation, row.proof_generation, session.semantic_generation, session.proof_generation);
    return ResolveOut {
        found: found,
        generation: select(found, b.generation, 0),
        artifact: select(found, b.artifact, 0),
        state_code: select(found, b.state_code, 0),
        proof_current: current,
    };
}

// --- Executable entry points (scalar shapes for backend corpora) ---

fn nodeps() -> (result: [u64; 4]) {
    return [0, 0, 0, 0];
}

// Define, compile, publish, resolve: the binding swings to
// generation 1 / artifact 1, Valid, proof-current; the artifact is
// Active with publish_seq 1.
fn candidate_publish_flow() -> (result: i64) {
    let s0: types.Session = session.create();
    let d1: session.DefineOut = session.define(s0, 0, 100, 0, 0, nodeps(), 0, 0);
    let n1: NoteOut = note_compiled(d1.session, 1, 1, 1, 12, 1, 1, 0);
    let p1: PublishOut = publish(n1.session, 1, 1);
    let r: ResolveOut = resolve(p1.session, 1);
    let a: session.ArtifactQuery = session.artifact_of(p1.session, 1);
    return select(p1.accepted, 100000000, 0) as i64
        +% r.generation as i64 *% 1000000
        +% r.artifact as i64 *% 100000
        +% r.state_code as i64 *% 10000
        +% select(r.proof_current, 1000, 0) as i64
        +% a.lifecycle_code as i64 *% 100
        +% a.publish_seq as i64;
}

// Supersession: publishing generation 2 demotes artifact 1 to
// Published while artifact 2 goes Active; the binding follows.
fn candidate_supersede() -> (result: i64) {
    let s0: types.Session = session.create();
    let d1: session.DefineOut = session.define(s0, 0, 100, 0, 0, nodeps(), 0, 0);
    let n1: NoteOut = note_compiled(d1.session, 1, 1, 1, 12, 1, 1, 0);
    let p1: PublishOut = publish(n1.session, 1, 1);
    let d2: session.DefineOut = session.define(p1.session, 1, 200, 0, 0, nodeps(), 0, 0);
    let n2: NoteOut = note_compiled(d2.session, 1, 2, 1, 15, 1, 1, 0);
    let p2: PublishOut = publish(n2.session, 1, 2);
    let r: ResolveOut = resolve(p2.session, 1);
    let old: session.ArtifactQuery = session.artifact_of(p2.session, 1);
    let new: session.ArtifactQuery = session.artifact_of(p2.session, 2);
    return r.generation as i64 *% 1000000
        +% r.artifact as i64 *% 100000
        +% old.lifecycle_code as i64 *% 10000
        +% new.lifecycle_code as i64 *% 1000
        +% new.publish_seq as i64 *% 100
        +% select(p2.accepted, 10, 0) as i64
        +% r.state_code as i64;
}

// Abandon: after a failed second generation, rollback restores
// generation 1 / artifact 1 as Valid.
fn candidate_abandon() -> (result: i64) {
    let s0: types.Session = session.create();
    let d1: session.DefineOut = session.define(s0, 0, 100, 0, 0, nodeps(), 0, 0);
    let n1: NoteOut = note_compiled(d1.session, 1, 1, 1, 12, 1, 1, 0);
    let p1: PublishOut = publish(n1.session, 1, 1);
    let d2: session.DefineOut = session.define(p1.session, 1, 200, 0, 0, nodeps(), 0, 0);
    let mid: ResolveOut = resolve(d2.session, 1);
    let back: AbandonOut = abandon(d2.session, 1);
    let r: ResolveOut = resolve(back.session, 1);
    return mid.state_code as i64 *% 1000000
        +% select(back.restored, 100000, 0) as i64
        +% r.generation as i64 *% 10000
        +% r.artifact as i64 *% 1000
        +% r.state_code as i64 *% 100
        +% select(r.proof_current, 10, 0) as i64
        +% mid.artifact as i64;
}

// Retire the active artifact: the binding goes Stale with reason 4
// and republication of the retired code is refused (reason 4).
fn candidate_retire() -> (result: i64) {
    let s0: types.Session = session.create();
    let d1: session.DefineOut = session.define(s0, 0, 100, 0, 0, nodeps(), 0, 0);
    let n1: NoteOut = note_compiled(d1.session, 1, 1, 1, 12, 1, 1, 0);
    let p1: PublishOut = publish(n1.session, 1, 1);
    let k1: RetireArtifactOut = retire_artifact(p1.session, 1);
    let r: ResolveOut = resolve(k1.session, 1);
    let repub: PublishOut = publish(k1.session, 1, 1);
    let q: session.BindingQuery = session.binding_of(k1.session, 1);
    return select(k1.retired, 1000000, 0) as i64
        +% r.state_code as i64 *% 100000
        +% q.stale_reason as i64 *% 10000
        +% repub.reason as i64 *% 1000
        +% select(repub.accepted, 100, 0) as i64
        +% r.artifact as i64;
}

// Stale proof: advancing the era then publishing an artifact bound
// to the old triple is refused (reason 5); resolve reports the old
// binding as proof-stale.
fn candidate_stale_proof() -> (result: i64) {
    let s0: types.Session = session.create();
    let d1: session.DefineOut = session.define(s0, 0, 100, 0, 0, nodeps(), 0, 0);
    let n1: NoteOut = note_compiled(d1.session, 1, 1, 1, 12, 1, 1, 0);
    let p1: PublishOut = publish(n1.session, 1, 1);
    let aged: types.Session = session.advance_proof(p1.session);
    let d2: session.DefineOut = session.define(aged, 1, 200, 0, 0, nodeps(), 0, 0);
    let n2: NoteOut = note_compiled(d2.session, 1, 2, 1, 15, 1, 1, 0);
    let p2: PublishOut = publish(n2.session, 1, 2);
    let r: ResolveOut = resolve(p1.session, 1);
    let r2: ResolveOut = resolve(aged, 1);
    return p2.reason as i64 *% 100000
        +% select(p2.accepted, 10000, 0) as i64
        +% select(r.proof_current, 1000, 0) as i64
        +% select(r2.proof_current, 100, 0) as i64
        +% r2.state_code as i64 *% 10
        +% r2.generation as i64;
}

// Note guards: unknown logical (3), stale generation (5),
// unimplemented provider (6), unknown provider (4).
fn candidate_note_guards() -> (result: i64) {
    let s0: types.Session = session.create();
    let d1: session.DefineOut = session.define(s0, 0, 100, 0, 0, nodeps(), 0, 0);
    let ghost: NoteOut = note_compiled(d1.session, 99, 1, 1, 5, 1, 1, 0);
    let stale: NoteOut = note_compiled(d1.session, 1, 99, 1, 5, 1, 1, 0);
    let future: NoteOut = note_compiled(d1.session, 1, 1, 2, 5, 1, 1, 0);
    let bogus: NoteOut = note_compiled(d1.session, 1, 1, 9, 5, 1, 1, 0);
    let good: NoteOut = note_compiled(d1.session, 1, 1, 0, 5, 1, 1, 0);
    return ghost.reason as i64 *% 100000
        +% stale.reason as i64 *% 10000
        +% future.reason as i64 *% 1000
        +% bogus.reason as i64 *% 100
        +% good.artifact_code as i64 *% 10
        +% select(good.accepted, 1, 0) as i64;
}

mncs 0.13;

// mncs.jit.depends — dependency edges and invalidation for the
// MNCS-native JIT orchestration layer.
//
// An edge `DepEdge { user, used, kind_code }` records that logical
// definition `user` observes definition `used` through `kind_code`
// (the `mncs.jit.types.v1` DepKind table: 0 Call, 1 Signature,
// 2 Layout). Nodes are host-assigned u64 logical identities; the
// session allocator starts them at 1, so 0 is always a sentinel.
//
// INVALIDATION POLICY (explicit, no incidental backend behavior):
//   change BodyOnly(0)    -> every dependent Unaffected(0).
//   change Signature(1)   -> Call edge: RequiresRecompile(2);
//                            Signature edge: RequiresRecompile(2);
//                            Layout edge: ValidRoutesNew(1): layout is
//                            preserved, so the dependent keeps its
//                            binding and picks up the new generation
//                            once published, with no rebuild.
//   change Contract(2)    -> every dependent RequiresRecompile(2):
//                            proof/capability assumptions changed.
// Transitive dependents (depth >= 2) escalate: any change that forces
// review becomes RequiresRecompile, because an intermediary rebuild
// may alter observable behavior; BodyOnly stays Unaffected.
// Stale reasons reuse the binding table: 2 = dep-signature,
// 3 = dep-contract (change_code +% 1).
//
// All windows are bounded: edges <= 16, affected <= 8, closure rounds
// <= 8. Overflow and truncation are explicit verdicts, never silent
// loss. Every function is total; every operation is a bounded fold.
//
// Complexity bounds: insert/contains <= E comparisons; direct-user
// scan <= E; closure <= rounds * (E * V); stale application
// <= bindings * affected. No operation allocates.
module mncs.jit.depends.v1;

use mncs.core.logic.v1 as logic;
use mncs.jit.types.v1 as types;

// --- Edge storage ---

record EdgeInsertOut {
    edges: [types.DepEdge; 16],
    count: u64,
    accepted: bool,
}

fn edge_known(edges: [types.DepEdge; 16], count: u64, user: u64, used: u64) -> (result: bool) {
    iterate i over edges carrying found: bool = false {
        let live: bool = i < count;
        next found = found || (live && edges[i].user == user && edges[i].used == used);
    }
    return found;
}

// Insert with deduplication (first edge kind wins; see the module
// header). A present edge, an unknown kind, and a full store all
// report rejected with the storage unchanged.
fn insert_edge(edges: [types.DepEdge; 16], count: u64, user: u64, used: u64, kind_code: u64) -> (result: EdgeInsertOut) {
    let full: bool = count >= 16;
    let known: bool = edge_known(edges, count, user, used);
    let kind_ok: bool = types.dep_kind_is_known(kind_code);
    let accepted: bool = logic.bool_not(full) && logic.bool_not(known) && kind_ok;
    let slot: u64 = select(accepted, count, 0);
    let grown: [types.DepEdge; 16] = replace(edges, slot, types.DepEdge { user: user, used: used, kind_code: kind_code });
    if accepted {
        return EdgeInsertOut { edges: grown, count: count +% 1, accepted: true };
    } else {
    }
    return EdgeInsertOut { edges: edges, count: count, accepted: false };
}

// --- Per-edge verdict ---

// Explicit policy matrix from the module header. Unknown change or
// kind codes fail closed to RequiresRecompile: an unrecognized change
// must never read as Unaffected.
fn classify_dependent(change_code: u64, kind_code: u64) -> (result: u64) {
    if logic.bool_not(types.change_is_known(change_code)) {
        return 2;
    }
    if logic.bool_not(types.dep_kind_is_known(kind_code)) {
        return 2;
    }
    if change_code == 0 {
        return 0;
    }
    if change_code == 2 {
        return 2;
    }
    if kind_code == 2 {
        return 1;
    }
    return 2;
}

// Escalation for transitive dependents: review-forcing changes become
// RequiresRecompile; BodyOnly stays Unaffected.
fn escalate_transitive(change_code: u64) -> (result: u64) {
    if types.change_forces_dependent_review(change_code) {
        return 2;
    }
    return 0;
}

fn stale_reason_for(change_code: u64) -> (result: u64) {
    return change_code +% 1;
}

// --- Direct users with edge kinds ---

record DirectOut {
    users: [u64; 8],
    kinds: [u64; 8],
    count: u64,
    truncated: bool,
}

fn direct_has(users: [u64; 8], count: u64, node: u64) -> (result: bool) {
    iterate i over users carrying found: bool = false {
        next found = found || (i < count && users[i] == node);
    }
    return found;
}

// Direct users of `changed` with the first recorded edge kind each.
// At most 8 users; further nominations set `truncated`.
fn direct_users(edges: [types.DepEdge; 16], count: u64, changed: u64) -> (result: DirectOut) {
    let seed: DirectOut = DirectOut {
        users: [0, 0, 0, 0, 0, 0, 0, 0],
        kinds: [0, 0, 0, 0, 0, 0, 0, 0],
        count: 0,
        truncated: false,
    };
    iterate i over edges carrying st: DirectOut = seed {
        let live: bool = i < count;
        let edge: types.DepEdge = edges[i];
        let nominated: bool = live && edge.used == changed && logic.bool_not(direct_has(st.users, st.count, edge.user));
        let room: bool = st.count < 8;
        let join: bool = nominated && room;
        let slot: u64 = select(join, st.count, 0);
        next st = DirectOut {
            users: replace(st.users, slot, select(join, edge.user, st.users[slot])),
            kinds: replace(st.kinds, slot, select(join, edge.kind_code, st.kinds[slot])),
            count: st.count +% select(join, 1, 0) as u64,
            truncated: st.truncated || (nominated && logic.bool_not(room)),
        };
    }
    return st;
}

// --- Transitive dependents (reversed-edge closure) ---

record DependentsOut {
    affected: [u64; 8],
    count: u64,
    truncated: bool,
}

fn affected_has(reached: [u64; 8], count: u64, node: u64) -> (result: bool) {
    iterate i over reached carrying found: bool = false {
        next found = found || (i < count && reached[i] == node);
    }
    return found;
}

// One breadth-first round over reversed edges: every edge whose
// `used` endpoint is already reached nominates its `user`. A frozen
// round (`active` false) is the identity, so the depth loop runs a
// fixed 8 rounds with no record-valued select.
fn depend_round(edges: [types.DepEdge; 16], count: u64, base: [u64; 8], base_count: u64, st: DependentsOut, active: bool) -> (result: DependentsOut) {
    iterate i over edges carrying acc: DependentsOut = st {
        let live: bool = i < count;
        let edge: types.DepEdge = edges[i];
        let nominated: bool = live && affected_has(base, base_count, edge.used) && logic.bool_not(affected_has(acc.affected, acc.count, edge.user));
        let room: bool = acc.count < 8;
        let join: bool = nominated && room && active;
        let slot: u64 = select(join, acc.count, 0);
        next acc = DependentsOut {
            affected: replace(acc.affected, slot, select(join, edge.user, acc.affected[slot])),
            count: acc.count +% select(join, 1, 0) as u64,
            truncated: acc.truncated || (nominated && logic.bool_not(room) && active),
        };
    }
    return acc;
}

record DependFold {
    st: DependentsOut,
    round: u64,
}

// Seeding: the first round expands from the round-start frontier, so
// the changed node enters the frontier explicitly at depth zero. Each
// later round adds exactly the next hop, so `max_depth` bounds hops.
fn dependents_seeded(edges: [types.DepEdge; 16], count: u64, changed: u64, max_depth: u64) -> (result: DependentsOut) {
    let seed: DependentsOut = DependentsOut {
        affected: [changed, 0, 0, 0, 0, 0, 0, 0],
        count: 1,
        truncated: false,
    };
    let fold_seed: DependFold = DependFold { st: seed, round: 0 };
    iterate round up_to 8 carrying fold: DependFold = fold_seed {
        let frontier: [u64; 8] = fold.st.affected;
        let frontier_count: u64 = fold.st.count;
        let acc: DependentsOut = fold.st;
        next fold = DependFold {
            st: depend_round(edges, count, frontier, frontier_count, acc, fold.round < max_depth),
            round: fold.round +% 1,
        };
    }
    // Drop the changed node from position 0; the window otherwise
    // holds reached users in discovery order. Projections bind one
    // level at a time: only single-level `name.field[i]` chains parse.
    let reached: [u64; 8] = fold.st.affected;
    let out: DependentsOut = DependentsOut {
        affected: [reached[1], reached[2], reached[3], reached[4], reached[5], reached[6], reached[7], 0],
        count: fold.st.count -% 1,
        truncated: fold.st.truncated,
    };
    return out;
}

// --- Apply verdicts to a binding window ---

record StaleOut {
    bindings: [types.Binding; 8],
    staled: u64,
    routed: u64,
    truncated: bool,
}

fn direct_kind(users: [u64; 8], kinds: [u64; 8], count: u64, node: u64) -> (result: u64) {
    iterate i over users carrying kind: u64 = 0 {
        let hit: bool = i < count && users[i] == node;
        next kind = select(hit, kinds[i], kind);
    }
    return kind;
}

// Mark dependents of `changed` stale in a binding window. The changed
// definition's own binding is left to its caller (redefinition owns
// that transition). Direct users take the policy-matrix verdict for
// their edge kind; transitive-only users escalate. Only Valid
// bindings transition; already-Stale bindings keep their reason.
// Returns the updated window plus stale/routed counts.
fn stale_bindings(edges: [types.DepEdge; 16], edge_count: u64, bindings: [types.Binding; 8], binding_count: u64, changed: u64, change_code: u64) -> (result: StaleOut) {
    let direct: DirectOut = direct_users(edges, edge_count, changed);
    let reach: DependentsOut = dependents_seeded(edges, edge_count, changed, 8);
    let reason: u64 = stale_reason_for(change_code);
    let seed: StaleOut = StaleOut { bindings: bindings, staled: 0, routed: 0, truncated: direct.truncated || reach.truncated };
    iterate i over bindings carrying st: StaleOut = seed {
        let live: bool = i < binding_count;
        let b: types.Binding = st.bindings[i];
        let is_changed: bool = b.logical == changed;
        let is_valid: bool = b.state_code == 0;
        let hit: bool = live && logic.bool_not(is_changed) && is_valid && affected_has(reach.affected, reach.count, b.logical);
        let is_direct: bool = direct_has(direct.users, direct.count, b.logical);
        let verdict: u64 = select(is_direct, classify_dependent(change_code, direct_kind(direct.users, direct.kinds, direct.count, b.logical)), escalate_transitive(change_code));
        let stale_now: bool = hit && verdict == 2;
        let routed_now: bool = hit && verdict == 1;
        let slot: u64 = select(stale_now, i, 0);
        let next_b: types.Binding = types.Binding {
            logical: b.logical,
            generation: b.generation,
            artifact: b.artifact,
            previous_generation: b.previous_generation,
            previous_artifact: b.previous_artifact,
            state_code: select(stale_now, 1, b.state_code),
            stale_reason: select(stale_now, reason, b.stale_reason),
        };
        next st = StaleOut {
            bindings: replace(st.bindings, slot, select_binding(stale_now, next_b, st.bindings[slot])),
            staled: st.staled +% select(stale_now, 1, 0) as u64,
            routed: st.routed +% select(routed_now, 1, 0) as u64,
            truncated: st.truncated,
        };
    }
    return st;
}

// Edge-typed conditional for callers that fold edge windows.
fn select_binding_edge(flag: bool, a: types.DepEdge, b: types.DepEdge) -> (result: types.DepEdge) {
    return types.DepEdge {
        user: select(flag, a.user, b.user),
        used: select(flag, a.used, b.used),
        kind_code: select(flag, a.kind_code, b.kind_code),
    };
}

// Record-typed conditional without a composite-valued select: both
// arms are bindings, the flag picks fields. (The language forbids
// composite-valued `select`; field-wise rebuilds are the pattern.)
fn select_binding(flag: bool, a: types.Binding, b: types.Binding) -> (result: types.Binding) {
    return types.Binding {
        logical: select(flag, a.logical, b.logical),
        generation: select(flag, a.generation, b.generation),
        artifact: select(flag, a.artifact, b.artifact),
        previous_generation: select(flag, a.previous_generation, b.previous_generation),
        previous_artifact: select(flag, a.previous_artifact, b.previous_artifact),
        state_code: select(flag, a.state_code, b.state_code),
        stale_reason: select(flag, a.stale_reason, b.stale_reason),
    };
}

