// mncs.jit.plan — provider-neutral execution planning for the
// MNCS-native JIT orchestration layer.
//
// Planning answers three questions without naming provider
// internals: which provider serves a workload class, which tier a
// definition sits in, and whether a concrete (logical, generation,
// artifact, provider, tier) tuple forms a plannable unit.
//
// PROVIDER SELECTION (first policy; thresholds stay parameters):
//   OneShot(0)     -> Reference(0): tiny/one-shot expressions run
//     directly; no native compile is spent on them.
//   Interactive(1) -> Cranelift(1) when ready and implemented;
//     otherwise Reference(0) with deferred=true: an explicit
//     degraded route, never a silent substitution.
//   HotStable(2)   -> Cranelift(1) when ready (llvm_advisory=true
//     records LLVM candidacy for the future optimizer); otherwise
//     Reference(0) with deferred=true.
//   Accelerator(3) -> refused (ok=false): no accelerator provider
//     exists, and planning must not fake one.
// Unknown workload codes are refused. Readiness flags are host
// observations threaded in by the driver; the policy only decides.
//
// TIER POLICY: `recommend_tier` takes its warm/hot call thresholds
// as parameters, so future adaptive policies tune them without
// touching this module. `hot_candidate` additionally gates on total
// execution time, so a cold-but-chatty definition does not promote.
//
// A plan binds one logical definition generation to one artifact on
// one provider at one tier. `build_plan` accepts only nonzero
// identities, implemented providers, and known tiers.
//
// Complexity bounds: all decisions are O(1). No operation
// allocates; every function is total.
module mncs.jit.plan.v1;

use mncs.core.logic.v1 as logic;
use mncs.jit.types.v1 as types;

// Provider selection outcome. `ok` false means no provider was
// selected (nothing executes); `deferred` true means the route is
// degraded (Reference fallback) and should be revisited;
// `llvm_advisory` true marks a hot definition as a future LLVM
// tiering candidate. provider_code 9 is the refused sentinel.
record PlanDecision {
    provider_code: u64,
    ok: bool,
    deferred: bool,
    llvm_advisory: bool,
}

fn select_provider(class_code: u64, cranelift_ready: bool, llvm_ready: bool) -> (result: PlanDecision) {
    if logic.bool_not(types.workload_is_known(class_code)) {
        return PlanDecision { provider_code: 9, ok: false, deferred: false, llvm_advisory: false };
    }
    if class_code == 0 {
        return PlanDecision { provider_code: 0, ok: true, deferred: false, llvm_advisory: false };
    }
    if class_code == 3 {
        return PlanDecision { provider_code: 9, ok: false, deferred: false, llvm_advisory: false };
    }
    if cranelift_ready && types.provider_is_implemented(1) {
        return PlanDecision { provider_code: 1, ok: true, deferred: false, llvm_advisory: class_code == 2 && llvm_ready };
    } else {
    }
    return PlanDecision { provider_code: 0, ok: true, deferred: true, llvm_advisory: false };
}

// Tier recommendation from call counts against caller-supplied
// thresholds. Inverted thresholds (hot below warm) fail closed to
// Cold: a misconfigured policy must not promote.
fn recommend_tier(calls: u64, warm_threshold: u64, hot_threshold: u64) -> (result: u64) {
    if hot_threshold < warm_threshold {
        return 0;
    }
    if calls >= hot_threshold {
        return 2;
    }
    if calls >= warm_threshold {
        return 1;
    }
    return 0;
}

// Promotion candidacy: enough calls AND enough total execution time.
// Both thresholds are parameters.
fn hot_candidate(calls: u64, exec_ms_total: u64, call_threshold: u64, ms_threshold: u64) -> (result: bool) {
    return calls >= call_threshold && exec_ms_total >= ms_threshold;
}

record Plan {
    logical: u64,
    generation: u64,
    artifact: u64,
    provider_code: u64,
    tier_code: u64,
    accepted: bool,
}

// A plan is accepted only for nonzero identities, an implemented
// provider, and a known tier. Anything else is an explicit reject;
// the caller keeps its previous plan.
fn build_plan(logical: u64, generation: u64, artifact: u64, provider_code: u64, tier_code: u64) -> (result: Plan) {
    let ok: bool = logical != 0 && generation != 0 && artifact != 0 && types.provider_is_implemented(provider_code) && types.tier_is_known(tier_code);
    if ok {
        return Plan { logical: logical, generation: generation, artifact: artifact, provider_code: provider_code, tier_code: tier_code, accepted: true };
    } else {
    }
    return Plan { logical: 0, generation: 0, artifact: 0, provider_code: 9, tier_code: 0, accepted: false };
}

// --- Executable entry points (scalar shapes for backend corpora) ---

// Selection rows: OneShot, Interactive ready/unready, HotStable
// ready/unready, Accelerator, unknown class. Packed provider codes
// (9 = refused): 0 1 0 1 0 9 9 -> 0101099.
fn candidate_selection_rows() -> (result: i64) {
    let one: PlanDecision = select_provider(0, true, false);
    let int_ready: PlanDecision = select_provider(1, true, false);
    let int_down: PlanDecision = select_provider(1, false, false);
    let hot_ready: PlanDecision = select_provider(2, true, true);
    let hot_down: PlanDecision = select_provider(2, false, false);
    let accel: PlanDecision = select_provider(3, true, true);
    let unknown: PlanDecision = select_provider(9, true, true);
    return one.provider_code as i64 *% 1000000
        +% int_ready.provider_code as i64 *% 100000
        +% int_down.provider_code as i64 *% 10000
        +% hot_ready.provider_code as i64 *% 1000
        +% hot_down.provider_code as i64 *% 100
        +% accel.provider_code as i64 *% 10
        +% unknown.provider_code as i64;
}

// Flags: Interactive-down defers, HotStable-ready advises LLVM,
// Accelerator and unknown refuse, OneShot is direct.
fn candidate_selection_flags() -> (result: i64) {
    let int_down: PlanDecision = select_provider(1, false, false);
    let hot_ready: PlanDecision = select_provider(2, true, true);
    let hot_no_llvm: PlanDecision = select_provider(2, true, false);
    let accel: PlanDecision = select_provider(3, true, true);
    let one: PlanDecision = select_provider(0, true, false);
    return select(int_down.deferred, 10000, 0) as i64
        +% select(hot_ready.llvm_advisory, 1000, 0) as i64
        +% select(hot_no_llvm.llvm_advisory, 100, 0) as i64
        +% select(accel.ok, 10, 0) as i64
        +% select(one.deferred, 1, 0) as i64;
}

// Tier boundaries at warm=10, hot=100: 9->Cold, 10->Warm, 99->Warm,
// 100->Hot; inverted thresholds pin Cold; candidacy gates both axes.
fn candidate_tier_policy() -> (result: i64) {
    let cold: u64 = recommend_tier(9, 10, 100);
    let warm: u64 = recommend_tier(10, 10, 100);
    let warm_hi: u64 = recommend_tier(99, 10, 100);
    let hot: u64 = recommend_tier(100, 10, 100);
    let invert: u64 = recommend_tier(1000, 100, 10);
    let cand: bool = hot_candidate(100, 5000, 100, 5000);
    let chatty: bool = hot_candidate(100000, 3, 100, 5000);
    return cold as i64 *% 1000000 +% warm as i64 *% 100000 +% warm_hi as i64 *% 10000 +% hot as i64 *% 1000 +% invert as i64 *% 100 +% select(cand, 10, 0) as i64 +% select(chatty, 1, 0) as i64;
}

// Plan acceptance: valid tuple accepted; zero artifact, LLVM
// provider, and unknown tier each rejected.
fn candidate_plan_accept() -> (result: i64) {
    let good: Plan = build_plan(1, 2, 7, 1, 0);
    let zero_art: Plan = build_plan(1, 2, 0, 1, 0);
    let llvm: Plan = build_plan(1, 2, 7, 2, 0);
    let tier: Plan = build_plan(1, 2, 7, 1, 9);
    return select(good.accepted, 1000, 0) as i64 +% select(zero_art.accepted, 100, 0) as i64 +% select(llvm.accepted, 10, 0) as i64 +% select(tier.accepted, 1, 0) as i64;
}

mncs 0.13;

// mncs.jit.profile — execution observations and tiering hooks for the
// MNCS-native JIT orchestration layer.
//
// A Profile is per-(logical, generation, provider) accounting owned
// by the session layer; the host threads wall-clock milliseconds in
// (the `clock` pattern: time enters only as host observations, never
// as ambient reads). Observations are total and saturating: counters
// pin at u64 MAX instead of wrapping, so a hot loop can never turn
// its own accounting into a cold reading.
//
// This module deliberately stops at hooks: call/execution/compile
// accounting, means, and threshold-gated candidacy. Adaptive
// optimization policy lives above (see `mncs.jit.plan.v1`); the only
// contract here is that every number a future tiering policy needs
// is already recorded with explicit units (milliseconds).
//
// Complexity bounds: every observation is O(1). No operation
// allocates; every function is total.
module mncs.jit.profile.v1;

use mncs.core.logic.v1 as logic;

// Per-executable-generation accounting. provider_code and generation
// identify the subject; the session layer re-keys on republication.
record Profile {
    calls: u64,
    exec_ms_total: u64,
    compile_ms_total: u64,
    last_exec_ms: u64,
    provider_code: u64,
    generation: u64,
}

fn profile_zero() -> (result: Profile) {
    return Profile { calls: 0, exec_ms_total: 0, compile_ms_total: 0, last_exec_ms: 0, provider_code: 0, generation: 0 };
}

// Saturating addition: pins at u64 MAX (18446744073709551615).
// Wrapping here would be dishonest accounting, so the bound is
// checked before the add and no trap is possible.
fn saturating_add(a: u64, b: u64) -> (result: u64) {
    let max: u64 = 18446744073709551615;
    if a > max -% b {
        return max;
    }
    return a +% b;
}

// Record one invocation observed at `exec_ms` milliseconds.
fn observe_call(p: Profile, exec_ms: u64, provider_code: u64, generation: u64) -> (result: Profile) {
    return Profile {
        calls: saturating_add(p.calls, 1),
        exec_ms_total: saturating_add(p.exec_ms_total, exec_ms),
        compile_ms_total: p.compile_ms_total,
        last_exec_ms: exec_ms,
        provider_code: provider_code,
        generation: generation,
    };
}

// Record one compilation observed at `compile_ms` milliseconds.
fn observe_compile(p: Profile, compile_ms: u64) -> (result: Profile) {
    return Profile {
        calls: p.calls,
        exec_ms_total: p.exec_ms_total,
        compile_ms_total: saturating_add(p.compile_ms_total, compile_ms),
        last_exec_ms: p.last_exec_ms,
        provider_code: p.provider_code,
        generation: p.generation,
    };
}

// Mean execution milliseconds per call; 0 before any call. The
// division sits behind the zero guard because `select` is strict.
fn mean_exec_ms(p: Profile) -> (result: u64) {
    if p.calls == 0 {
        return 0;
    } else {
    }
    return p.exec_ms_total / p.calls;
}

// True once the subject has served at least `min_calls` calls. The
// threshold is a parameter: steady-state detection policy lives
// above this module.
fn is_steady(p: Profile, min_calls: u64) -> (result: bool) {
    return p.calls >= min_calls;
}

// --- Executable entry points (scalar shapes for backend corpora) ---

// Saturation edge: MAX stays MAX under further adds, and MAX -% b
// arithmetic never traps.
fn candidate_saturation() -> (result: i64) {
    let top: u64 = saturating_add(18446744073709551615, 1);
    let near: u64 = saturating_add(18446744073709551610, 4);
    let past: u64 = saturating_add(18446744073709551610, 5);
    let plain: u64 = saturating_add(100, 23);
    return select(top == 18446744073709551615, 1000, 0) as i64
        +% select(near == 18446744073709551614, 100, 0) as i64
        +% select(past == 18446744073709551615, 10, 0) as i64
        +% select(plain == 123, 1, 0) as i64;
}

// Observe chain: two calls (4ms, 6ms) plus a 50ms compile on
// provider 1 generation 3. calls=2, total=10, mean=5, compile=50,
// last=6, steady at 2 but not at 3.
fn candidate_observe_chain() -> (result: i64) {
    let p0: Profile = profile_zero();
    let p1: Profile = observe_call(p0, 4, 1, 3);
    let p2: Profile = observe_call(p1, 6, 1, 3);
    let p3: Profile = observe_compile(p2, 50);
    return p3.calls as i64 *% 100000000
        +% p3.exec_ms_total as i64 *% 1000000
        +% mean_exec_ms(p3) as i64 *% 100000
        +% p3.compile_ms_total as i64 *% 1000
        +% p3.last_exec_ms as i64 *% 10
        +% select(is_steady(p3, 2), 1, 0) as i64
        +% select(is_steady(p3, 3), 0, 0) as i64;
}

// Mean before any call is 0 (no division executed); a fresh profile
// is not steady at 1.
fn candidate_empty_profile() -> (result: i64) {
    let p0: Profile = profile_zero();
    return mean_exec_ms(p0) as i64 *% 10 +% select(is_steady(p0, 1), 1, 0) as i64;
}

mncs 0.13;

// mncs.jit.proof — proof-aware execution metadata for the MNCS-native
// JIT orchestration layer.
//
// Proof information is intrinsic execution metadata, not a bolt-on:
// every definition row and every compiled artifact carries the
// (semantic_generation, proof_generation, assumption_bits) triple
// under which it was validated, and publication refuses artifacts
// whose triple no longer matches the session's current era.
//
// The model is deliberately exact-match in this first step:
// assumption_bits compare for equality and never interpret
// kernel-owned bitmaps. Subset/capability reasoning is future work
// (recorded as pressure, not approximated here).
//
// The specialization flow is represented, not executed:
//   runtime observation -> candidate specialization
//     -> micro-verifier -> proof kernel validation
//     -> new executable generation.
// `admit_specialization` takes the micro-verifier and kernel verdicts
// as explicit evidence parameters: a specialization is admitted only
// when both accept. There is no path that admits an unvalidated
// specialization, and no speculative unsafe optimization exists to
// demonstrate tiering.
//
// INVALIDATION FLOW: when the proof era advances (session
// `advance_proof`), artifacts bound to the old triple fail
// `artifact_proof_valid`; bindings over them report proof-stale at
// resolve time, so the driver falls back, recompiles, or retires
// them through the ordinary lifecycle transitions.
//
// Complexity bounds: every check is O(1). No operation allocates;
// every function is total.
module mncs.jit.proof.v1;

use mncs.core.logic.v1 as logic;

// True when a (semantic, proof) pair validated `then` still matches
// the session era `now`. Assumption bits compare separately so
// callers can distinguish era drift from assumption drift.
fn proof_current(sem_then: u64, proof_then: u64, sem_now: u64, proof_now: u64) -> (result: bool) {
    return sem_then == sem_now && proof_then == proof_now;
}

// Exact assumption match. Subset semantics are future work; an
// inexact match today is invalid, never silently narrowed.
fn assumptions_match(art_bits: u64, required_bits: u64) -> (result: bool) {
    return art_bits == required_bits;
}

// Full artifact proof check: era currency plus exact assumptions.
// This is the predicate publication enforces.
fn artifact_proof_valid(art_sem: u64, art_proof: u64, art_bits: u64, sess_sem: u64, sess_proof: u64, required_bits: u64) -> (result: bool) {
    return proof_current(art_sem, art_proof, sess_sem, sess_proof) && assumptions_match(art_bits, required_bits);
}

record Specialization {
    base_generation: u64,
    assumption_bits: u64,
    validated: bool,
}

// Admit a candidate specialization only on dual evidence: the
// micro-verifier accepts the candidate AND the proof kernel
// validates it. Either refusal leaves it unvalidated; the record
// still carries the evidence for introspection.
fn admit_specialization(base_generation: u64, assumption_bits: u64, verifier_accepted: bool, kernel_accepted: bool) -> (result: Specialization) {
    return Specialization {
        base_generation: base_generation,
        assumption_bits: assumption_bits,
        validated: verifier_accepted && kernel_accepted,
    };
}

// --- Executable entry points (scalar shapes for backend corpora) ---

// Era matrix: same era valid; proof drift, semantic drift, and
// assumption drift each invalid; combined drift invalid.
fn candidate_era_matrix() -> (result: i64) {
    let same: bool = artifact_proof_valid(3, 7, 11, 3, 7, 11);
    let proof_drift: bool = artifact_proof_valid(3, 7, 11, 3, 8, 11);
    let sem_drift: bool = artifact_proof_valid(3, 7, 11, 4, 7, 11);
    let bits_drift: bool = artifact_proof_valid(3, 7, 11, 3, 7, 12);
    let all_drift: bool = artifact_proof_valid(3, 7, 11, 4, 8, 12);
    return select(same, 10000, 0) as i64
        +% select(proof_drift, 1000, 0) as i64
        +% select(sem_drift, 100, 0) as i64
        +% select(bits_drift, 10, 0) as i64
        +% select(all_drift, 1, 0) as i64;
}

// Dual-key admission: both accept -> validated; either refusal ->
// unvalidated; evidence (base, bits) always carried.
fn candidate_dual_key() -> (result: i64) {
    let full: Specialization = admit_specialization(5, 9, true, true);
    let no_verifier: Specialization = admit_specialization(5, 9, false, true);
    let no_kernel: Specialization = admit_specialization(5, 9, true, false);
    let neither: Specialization = admit_specialization(5, 9, false, false);
    return select(full.validated, 1000, 0) as i64
        +% select(no_verifier.validated, 100, 0) as i64
        +% select(no_kernel.validated, 10, 0) as i64
        +% select(neither.validated, 1, 0) as i64
        +% full.base_generation as i64 *% 10000
        +% full.assumption_bits as i64 *% 100000;
}

// proof_current distinguishes the two era axes independently.
fn candidate_axes() -> (result: i64) {
    let both: bool = proof_current(1, 2, 1, 2);
    let sem_only: bool = proof_current(1, 2, 9, 2);
    let proof_only: bool = proof_current(1, 2, 1, 9);
    return select(both, 100, 0) as i64 +% select(sem_only, 10, 0) as i64 +% select(proof_only, 1, 0) as i64;
}

mncs 0.13;

// mncs.jit.session — persistent JIT session state for the MNCS-native
// JIT orchestration layer.
//
// A Session is a persistent VALUE threaded explicitly between calls
// by the host (the `task` pattern): the language keeps no ambient
// store, so creation, destruction, and every transition are
// deterministic functions of the threaded value. Logical definition
// identities (`logical`) are allocator-owned codes starting at 1;
// 0 is always a sentinel (allocate-new / missing).
//
// GENERATIONAL MODEL: a logical definition owns a history of source
// generations (Definition rows, never mutated), each compiled zero
// or more times into Executable rows keyed by MNCS-assigned artifact
// codes. The Binding row selects at most one executable per logical
// definition. Old executables stay alive under explicit lifecycle
// states; redefinition never overwrites emitted code.
//
// DEFINE POLICY (`define` reasons):
//   0 ok-new, 1 ok-redefined,
//   2 rejected-closed, 3 rejected-defs-full, 4 rejected-duplicate,
//   5 rejected-edges-full, 6 rejected-unknown-logical,
//   7 rejected-unknown-change-or-kind.
// Every rejection returns the session unchanged with generation 0.
// A duplicate-content resubmission is not a new generation: it would
// spend a compile on identical bytes, so it is refused explicitly.
// Redefinition snapshots the current selection into previous_*
// (rollback support), points the binding at the new generation with
// no artifact (Stale, reason 1 = self-redefine), and marks review-
// forcing dependents stale through `mncs.jit.depends.v1`.
//
// ERA POLICY: `advance_proof` / `advance_semantic` bump the session
// era. Artifacts bound to older eras fail proof checks at publish
// and report proof-stale at resolve; nothing is silently
// revalidated. `close` freezes the session (closed=true), retires
// every live artifact, and retires every binding; mutating entry
// points reject closed sessions. Close is idempotent.
//
// Complexity bounds: define scans defs (<= 8), bindings (<= 8),
// edges (<= 16) plus one bounded stale pass; getters are single
// passes; close is two passes. No operation allocates; every
// function is total.
module mncs.jit.session.v1;

use mncs.core.logic.v1 as logic;
use mncs.jit.depends.v1 as depends;
use mncs.jit.lifecycle.v1 as lifecycle;
use mncs.jit.types.v1 as types;

record DefineOut {
    session: types.Session,
    logical: u64,
    generation: u64,
    accepted: bool,
    reason: u64,
}

record Counts {
    defs: u64,
    bindings: u64,
    artifacts: u64,
    edges: u64,
    semantic_generation: u64,
    proof_generation: u64,
    publish_seq: u64,
    closed: bool,
}

record BindingQuery {
    found: bool,
    generation: u64,
    artifact: u64,
    state_code: u64,
    stale_reason: u64,
}

record ArtifactQuery {
    found: bool,
    logical: u64,
    generation: u64,
    lifecycle_code: u64,
    provider_code: u64,
    publish_seq: u64,
}

record ProofQuery {
    found: bool,
    semantic_generation: u64,
    proof_generation: u64,
    assumption_bits: u64,
}

record EdgeFold {
    edges: [types.DepEdge; 16],
    count: u64,
}

// --- Zero values ---

fn zero_definition() -> (result: types.Definition) {
    return types.Definition {
        logical: 0,
        generation: 0,
        content_hash: 0,
        change_code: 0,
        semantic_generation: 0,
        proof_generation: 0,
        assumption_bits: 0,
        dep_count: 0,
    };
}

fn zero_binding() -> (result: types.Binding) {
    return types.Binding {
        logical: 0,
        generation: 0,
        artifact: 0,
        previous_generation: 0,
        previous_artifact: 0,
        state_code: 0,
        stale_reason: 0,
    };
}

fn zero_executable() -> (result: types.Executable) {
    return types.Executable {
        code: 0,
        logical: 0,
        generation: 0,
        provider_code: 0,
        lifecycle_code: 0,
        semantic_generation: 0,
        proof_generation: 0,
        assumption_bits: 0,
        compile_ms: 0,
        publish_seq: 0,
    };
}

fn zero_edge() -> (result: types.DepEdge) {
    return types.DepEdge { user: 0, used: 0, kind_code: 0 };
}

// --- Creation ---

fn create() -> (result: types.Session) {
    let d0: types.Definition = zero_definition();
    let b0: types.Binding = zero_binding();
    let a0: types.Executable = zero_executable();
    let e0: types.DepEdge = zero_edge();
    return types.Session {
        semantic_generation: 1,
        proof_generation: 1,
        next_logical: 1,
        next_generation: 1,
        next_artifact: 1,
        publish_seq: 0,
        closed: false,
        defs: [d0, d0, d0, d0, d0, d0, d0, d0],
        def_count: 0,
        bindings: [b0, b0, b0, b0, b0, b0, b0, b0],
        binding_count: 0,
        artifacts: [a0, a0, a0, a0, a0, a0, a0, a0, a0, a0, a0, a0, a0, a0, a0, a0],
        artifact_count: 0,
        edges: [e0, e0, e0, e0, e0, e0, e0, e0, e0, e0, e0, e0, e0, e0, e0, e0],
        edge_count: 0,
    };
}

// --- Scans ---

fn binding_index(session: types.Session, logical: u64) -> (result: u64) {
    let binds: [types.Binding; 8] = session.bindings;
    iterate i over binds carrying slot: u64 = session.binding_count {
        let hit: bool = i < session.binding_count && binds[i].logical == logical;
        next slot = select(hit, i, slot);
    }
    return slot;
}

fn latest_generation(session: types.Session, logical: u64) -> (result: u64) {
    let rows: [types.Definition; 8] = session.defs;
    iterate i over rows carrying gen: u64 = 0 {
        let hit: bool = i < session.def_count && rows[i].logical == logical;
        next gen = select(hit, rows[i].generation, gen);
    }
    return gen;
}

fn latest_hash(session: types.Session, logical: u64) -> (result: u64) {
    let rows: [types.Definition; 8] = session.defs;
    iterate i over rows carrying hash: u64 = 0 {
        let hit: bool = i < session.def_count && rows[i].logical == logical;
        next hash = select(hit, rows[i].content_hash, hash);
    }
    return hash;
}

// Rows append in global generation order, so the last row for a
// logical definition is its latest.
fn has_room_edges(session: types.Session, need: u64) -> (result: bool) {
    return need <= 16 as u64 -% session.edge_count;
}

// --- Definition ---

fn insert_dep_edges(session: types.Session, user: u64, deps: [u64; 4], dep_count: u64, kind_code: u64) -> (result: types.Session) {
    let seed: EdgeFold = EdgeFold { edges: session.edges, count: session.edge_count };
    iterate k over deps carrying fold: EdgeFold = seed {
        let live: bool = k < dep_count && k < 4;
        let edge: types.DepEdge = types.DepEdge { user: user, used: deps[select(live, k, 0 as u64)], kind_code: kind_code };
        let placed: depends.EdgeInsertOut = depends.insert_edge(fold.edges, fold.count, edge.user, edge.used, edge.kind_code);
        let take: bool = live && placed.accepted;
        next fold = EdgeFold {
            edges: select_edge_fold(take, placed.edges, fold.edges),
            count: fold.count +% select(take, 1, 0) as u64,
        };
    }
    return types.Session {
        semantic_generation: session.semantic_generation,
        proof_generation: session.proof_generation,
        next_logical: session.next_logical,
        next_generation: session.next_generation,
        next_artifact: session.next_artifact,
        publish_seq: session.publish_seq,
        closed: session.closed,
        defs: session.defs,
        def_count: session.def_count,
        bindings: session.bindings,
        binding_count: session.binding_count,
        artifacts: session.artifacts,
        artifact_count: session.artifact_count,
        edges: fold.edges,
        edge_count: fold.count,
    };
}

// Edge-window conditional without a composite-valued select.
fn select_edge_fold(flag: bool, a: [types.DepEdge; 16], b: [types.DepEdge; 16]) -> (result: [types.DepEdge; 16]) {
    iterate i over a carrying out: [types.DepEdge; 16] = b {
        let pick: types.DepEdge = a[i];
        let keep: types.DepEdge = out[i];
        next out = replace(out, i, depends.select_binding_edge(flag, pick, keep));
    }
    return out;
}

fn define(session: types.Session, logical: u64, content_hash: u64, change_code: u64, assumption_bits: u64, deps: [u64; 4], dep_count: u64, dep_kind_code: u64) -> (result: DefineOut) {
    if session.closed {
        return DefineOut { session: session, logical: 0, generation: 0, accepted: false, reason: 2 };
    } else {
    }
    if logic.bool_not(types.change_is_known(change_code)) {
        return DefineOut { session: session, logical: 0, generation: 0, accepted: false, reason: 7 };
    } else {
    }
    if dep_count > 0 && logic.bool_not(types.dep_kind_is_known(dep_kind_code)) {
        return DefineOut { session: session, logical: 0, generation: 0, accepted: false, reason: 7 };
    } else {
    }
    if dep_count > 4 {
        return DefineOut { session: session, logical: 0, generation: 0, accepted: false, reason: 5 };
    } else {
    }
    if logical == 0 {
        return define_new(session, content_hash, change_code, assumption_bits, deps, dep_count, dep_kind_code);
    } else {
    }
    return define_redefine(session, logical, content_hash, change_code, assumption_bits, deps, dep_count, dep_kind_code);
}

fn define_new(session: types.Session, content_hash: u64, change_code: u64, assumption_bits: u64, deps: [u64; 4], dep_count: u64, dep_kind_code: u64) -> (result: DefineOut) {
    if session.def_count >= 8 {
        return DefineOut { session: session, logical: 0, generation: 0, accepted: false, reason: 3 };
    } else {
    }
    if session.binding_count >= 8 {
        return DefineOut { session: session, logical: 0, generation: 0, accepted: false, reason: 3 };
    } else {
    }
    if logic.bool_not(has_room_edges(session, dep_count)) {
        return DefineOut { session: session, logical: 0, generation: 0, accepted: false, reason: 5 };
    } else {
    }
    let fresh: u64 = session.next_logical;
    let gen: u64 = session.next_generation;
    let row: types.Definition = types.Definition {
        logical: fresh,
        generation: gen,
        content_hash: content_hash,
        change_code: change_code,
        semantic_generation: session.semantic_generation,
        proof_generation: session.proof_generation,
        assumption_bits: assumption_bits,
        dep_count: dep_count,
    };
    let bind: types.Binding = types.Binding {
        logical: fresh,
        generation: gen,
        artifact: 0,
        previous_generation: 0,
        previous_artifact: 0,
        state_code: 1,
        stale_reason: 0,
    };
    let grown: types.Session = types.Session {
        semantic_generation: session.semantic_generation,
        proof_generation: session.proof_generation,
        next_logical: session.next_logical +% 1,
        next_generation: session.next_generation +% 1,
        next_artifact: session.next_artifact,
        publish_seq: session.publish_seq,
        closed: session.closed,
        defs: replace(session.defs, session.def_count, row),
        def_count: session.def_count +% 1,
        bindings: replace(session.bindings, session.binding_count, bind),
        binding_count: session.binding_count +% 1,
        artifacts: session.artifacts,
        artifact_count: session.artifact_count,
        edges: session.edges,
        edge_count: session.edge_count,
    };
    let placed: types.Session = insert_dep_edges(grown, fresh, deps, dep_count, dep_kind_code);
    return DefineOut { session: placed, logical: fresh, generation: gen, accepted: true, reason: 0 };
}

fn define_redefine(session: types.Session, logical: u64, content_hash: u64, change_code: u64, assumption_bits: u64, deps: [u64; 4], dep_count: u64, dep_kind_code: u64) -> (result: DefineOut) {
    let slot: u64 = binding_index(session, logical);
    if slot >= session.binding_count {
        return DefineOut { session: session, logical: 0, generation: 0, accepted: false, reason: 6 };
    } else {
    }
    if latest_hash(session, logical) == content_hash {
        return DefineOut { session: session, logical: 0, generation: 0, accepted: false, reason: 4 };
    } else {
    }
    if session.def_count >= 8 {
        return DefineOut { session: session, logical: 0, generation: 0, accepted: false, reason: 3 };
    } else {
    }
    if logic.bool_not(has_room_edges(session, dep_count)) {
        return DefineOut { session: session, logical: 0, generation: 0, accepted: false, reason: 5 };
    } else {
    }
    let gen: u64 = session.next_generation;
    let row: types.Definition = types.Definition {
        logical: logical,
        generation: gen,
        content_hash: content_hash,
        change_code: change_code,
        semantic_generation: session.semantic_generation,
        proof_generation: session.proof_generation,
        assumption_bits: assumption_bits,
        dep_count: dep_count,
    };
    let binds: [types.Binding; 8] = session.bindings;
    let cur: types.Binding = binds[slot];
    let moved: types.Binding = types.Binding {
        logical: logical,
        generation: gen,
        artifact: 0,
        previous_generation: cur.generation,
        previous_artifact: cur.artifact,
        state_code: 1,
        stale_reason: 1,
    };
    let grown: types.Session = types.Session {
        semantic_generation: session.semantic_generation,
        proof_generation: session.proof_generation,
        next_logical: session.next_logical,
        next_generation: session.next_generation +% 1,
        next_artifact: session.next_artifact,
        publish_seq: session.publish_seq,
        closed: session.closed,
        defs: replace(session.defs, session.def_count, row),
        def_count: session.def_count +% 1,
        bindings: replace(binds, slot, moved),
        binding_count: session.binding_count,
        artifacts: session.artifacts,
        artifact_count: session.artifact_count,
        edges: session.edges,
        edge_count: session.edge_count,
    };
    let placed: types.Session = insert_dep_edges(grown, logical, deps, dep_count, dep_kind_code);
    let staled: depends.StaleOut = depends.stale_bindings(placed.edges, placed.edge_count, placed.bindings, placed.binding_count, logical, change_code);
    let done: types.Session = types.Session {
        semantic_generation: placed.semantic_generation,
        proof_generation: placed.proof_generation,
        next_logical: placed.next_logical,
        next_generation: placed.next_generation,
        next_artifact: placed.next_artifact,
        publish_seq: placed.publish_seq,
        closed: placed.closed,
        defs: placed.defs,
        def_count: placed.def_count,
        bindings: staled.bindings,
        binding_count: placed.binding_count,
        artifacts: placed.artifacts,
        artifact_count: placed.artifact_count,
        edges: placed.edges,
        edge_count: placed.edge_count,
    };
    return DefineOut { session: done, logical: logical, generation: gen, accepted: true, reason: 1 };
}

// --- Era advance ---

fn advance_proof(session: types.Session) -> (result: types.Session) {
    return types.Session {
        semantic_generation: session.semantic_generation,
        proof_generation: session.proof_generation +% 1,
        next_logical: session.next_logical,
        next_generation: session.next_generation,
        next_artifact: session.next_artifact,
        publish_seq: session.publish_seq,
        closed: session.closed,
        defs: session.defs,
        def_count: session.def_count,
        bindings: session.bindings,
        binding_count: session.binding_count,
        artifacts: session.artifacts,
        artifact_count: session.artifact_count,
        edges: session.edges,
        edge_count: session.edge_count,
    };
}

fn advance_semantic(session: types.Session) -> (result: types.Session) {
    return types.Session {
        semantic_generation: session.semantic_generation +% 1,
        proof_generation: session.proof_generation,
        next_logical: session.next_logical,
        next_generation: session.next_generation,
        next_artifact: session.next_artifact,
        publish_seq: session.publish_seq,
        closed: session.closed,
        defs: session.defs,
        def_count: session.def_count,
        bindings: session.bindings,
        binding_count: session.binding_count,
        artifacts: session.artifacts,
        artifact_count: session.artifact_count,
        edges: session.edges,
        edge_count: session.edge_count,
    };
}

// --- Close ---

record CloseFold {
    bindings: [types.Binding; 8],
}

fn close(session: types.Session) -> (result: types.Session) {
    let retired: lifecycle.RetireOut = lifecycle.retire_window(session.artifacts, session.artifact_count);
    let seed: CloseFold = CloseFold { bindings: session.bindings };
    iterate i over session.bindings carrying fold: CloseFold = seed {
        let live: bool = i < session.binding_count;
        let b: types.Binding = fold.bindings[i];
        let shut: types.Binding = types.Binding {
            logical: b.logical,
            generation: b.generation,
            artifact: b.artifact,
            previous_generation: b.previous_generation,
            previous_artifact: b.previous_artifact,
            state_code: select(live, 2, b.state_code),
            stale_reason: b.stale_reason,
        };
        next fold = CloseFold { bindings: replace(fold.bindings, i, shut) };
    }
    return types.Session {
        semantic_generation: session.semantic_generation,
        proof_generation: session.proof_generation,
        next_logical: session.next_logical,
        next_generation: session.next_generation,
        next_artifact: session.next_artifact,
        publish_seq: session.publish_seq,
        closed: true,
        defs: session.defs,
        def_count: session.def_count,
        bindings: fold.bindings,
        binding_count: session.binding_count,
        artifacts: retired.artifacts,
        artifact_count: session.artifact_count,
        edges: session.edges,
        edge_count: session.edge_count,
    };
}

// --- Introspection ---

fn session_counts(session: types.Session) -> (result: Counts) {
    return Counts {
        defs: session.def_count,
        bindings: session.binding_count,
        artifacts: session.artifact_count,
        edges: session.edge_count,
        semantic_generation: session.semantic_generation,
        proof_generation: session.proof_generation,
        publish_seq: session.publish_seq,
        closed: session.closed,
    };
}

fn binding_of(session: types.Session, logical: u64) -> (result: BindingQuery) {
    let slot: u64 = binding_index(session, logical);
    let found: bool = slot < session.binding_count;
    let b: types.Binding = session.bindings[select(found, slot, 0)];
    return BindingQuery {
        found: found,
        generation: select(found, b.generation, 0),
        artifact: select(found, b.artifact, 0),
        state_code: select(found, b.state_code, 0),
        stale_reason: select(found, b.stale_reason, 0),
    };
}

fn artifact_of(session: types.Session, code: u64) -> (result: ArtifactQuery) {
    let arts: [types.Executable; 16] = session.artifacts;
    iterate i over arts carrying slot: u64 = session.artifact_count {
        let hit: bool = i < session.artifact_count && arts[i].code == code;
        next slot = select(hit, i, slot);
    }
    let found: bool = slot < session.artifact_count;
    let a: types.Executable = arts[select(found, slot, 0)];
    return ArtifactQuery {
        found: found,
        logical: select(found, a.logical, 0),
        generation: select(found, a.generation, 0),
        lifecycle_code: select(found, a.lifecycle_code, 0),
        provider_code: select(found, a.provider_code, 0),
        publish_seq: select(found, a.publish_seq, 0),
    };
}

fn definition_proof(session: types.Session, logical: u64, generation: u64) -> (result: ProofQuery) {
    let rows: [types.Definition; 8] = session.defs;
    iterate i over rows carrying slot: u64 = session.def_count {
        let hit: bool = i < session.def_count && rows[i].logical == logical && rows[i].generation == generation;
        next slot = select(hit, i, slot);
    }
    let found: bool = slot < session.def_count;
    let row: types.Definition = rows[select(found, slot, 0)];
    return ProofQuery {
        found: found,
        semantic_generation: select(found, row.semantic_generation, 0),
        proof_generation: select(found, row.proof_generation, 0),
        assumption_bits: select(found, row.assumption_bits, 0),
    };
}

// --- Executable entry points (scalar shapes for backend corpora) ---

fn no_deps() -> (result: [u64; 4]) {
    return [0, 0, 0, 0];
}

// Create then define one BodyOnly definition: logical 1,
// generation 1, accepted, reason 0; counts 1/1/0/0.
fn candidate_create_define() -> (result: i64) {
    let s0: types.Session = create();
    let d1: DefineOut = define(s0, 0, 100, 0, 0, no_deps(), 0, 0);
    let c: Counts = session_counts(d1.session);
    return d1.logical as i64 *% 100000000
        +% d1.generation as i64 *% 1000000
        +% select(d1.accepted, 100000, 0) as i64
        +% d1.reason as i64 *% 10000
        +% c.defs as i64 *% 1000
        +% c.bindings as i64 *% 100
        +% c.artifacts as i64 *% 10
        +% c.edges as i64;
}

// Redefine with new content: generation 2, reason 1; the binding
// goes Stale(1) with reason 1; resubmitting the same hash is a
// duplicate (reason 4); unknown logical is rejected (reason 6).
fn candidate_redefine_flow() -> (result: i64) {
    let s0: types.Session = create();
    let d1: DefineOut = define(s0, 0, 100, 0, 0, no_deps(), 0, 0);
    let d2: DefineOut = define(d1.session, 1, 200, 1, 0, no_deps(), 0, 0);
    let q: BindingQuery = binding_of(d2.session, 1);
    let dup: DefineOut = define(d2.session, 1, 200, 1, 0, no_deps(), 0, 0);
    let ghost: DefineOut = define(d2.session, 99, 300, 0, 0, no_deps(), 0, 0);
    return d2.generation as i64 *% 100000000
        +% d2.reason as i64 *% 10000000
        +% q.state_code as i64 *% 1000000
        +% q.stale_reason as i64 *% 100000
        +% dup.reason as i64 *% 10000
        +% select(dup.accepted, 1000, 0) as i64
        +% ghost.reason as i64 *% 100
        +% latest_generation(d2.session, 1) as i64;
}

// Guard matrix: define on a closed session (2), unknown change (7),
// dependency window overflow (5), unknown dep kind (7).
fn candidate_guards() -> (result: i64) {
    let s0: types.Session = create();
    let shut: types.Session = close(s0);
    let on_closed: DefineOut = define(shut, 0, 100, 0, 0, no_deps(), 0, 0);
    let bad_change: DefineOut = define(s0, 0, 100, 9, 0, no_deps(), 0, 0);
    let wide: DefineOut = define(s0, 0, 100, 0, 0, [2, 3, 4, 5], 5, 0);
    let bad_kind: DefineOut = define(s0, 0, 100, 0, 0, [2, 0, 0, 0], 1, 9);
    return on_closed.reason as i64 *% 1000 +% bad_change.reason as i64 *% 100 +% wide.reason as i64 *% 10 +% bad_kind.reason as i64;
}

// Era advance bumps each axis independently; close freezes the
// session, retires bindings, and stays idempotent.
fn candidate_era_close() -> (result: i64) {
    let s0: types.Session = create();
    let s1: types.Session = advance_proof(s0);
    let s2: types.Session = advance_semantic(s1);
    let d1: DefineOut = define(s2, 0, 100, 0, 0, no_deps(), 0, 0);
    let shut: types.Session = close(d1.session);
    let shut2: types.Session = close(shut);
    let c: Counts = session_counts(shut2);
    let q: BindingQuery = binding_of(shut2, 1);
    return s1.proof_generation as i64 *% 100000000
        +% s2.semantic_generation as i64 *% 10000000
        +% select(c.closed, 1000000, 0) as i64
        +% q.state_code as i64 *% 100000
        +% c.publish_seq as i64 *% 10000
        +% c.defs as i64;
}

mncs 0.13;

// mncs.jit.types — shared vocabulary for the MNCS-native JIT/execution
// orchestration layer.
//
// This module owns the concept tables every other `mncs.jit.*` module
// builds on: providers, artifact lifecycles, execution tiers, change and
// dependency kinds, invalidation verdicts, binding validity, proof
// references, and the persistent session tables (definitions, logical
// bindings, compiled artifacts, dependency edges).
//
// BOUNDARY CONVENTION (host-assigned codes, the `token_set` pattern):
// records at rest carry u64 codes, never enum values, so cross-module
// construction and corpus boundaries stay scalar. The enums below are
// the checked vocabulary: converters live in this same module (where
// match exhaustiveness is verified), and every other module reads codes
// through `*_code` helpers or writes them through guarded `*_of`
// converters plus explicit `*_is_known` checks. Unknown codes always
// fail closed at the call site; they never reinterpret as a valid kind.
//
// Code tables (stable; a future `mncs-jit` extraction keeps these codes):
//   Provider   0 Reference (direct execution) | 1 Cranelift | 2 LLVM | 3 Native
//   Lifecycle  0 Empty | 1 Compiled | 2 Published | 3 Active | 4 Retired
//   Tier       0 Cold | 1 Warm | 2 Hot
//   ChangeKind 0 BodyOnly | 1 Signature | 2 Contract
//   DepKind    0 Call | 1 Signature | 2 Layout
//   DepVerdict 0 Unaffected | 1 ValidRoutesNew | 2 RequiresRecompile
//   Validity   0 Valid | 1 Stale | 2 Retired
//   Workload   0 OneShot | 1 Interactive | 2 HotStable | 3 Accelerator
//
// Table capacities (bounded, explicit-full verdicts, never silent loss):
//   definitions <= 8 source generations (history is retained)
//   bindings    <= 8 logical definitions
//   artifacts   <= 16 executable generations
//   edges       <= 16 dependency edges
//   define-time dependency window <= 4 edges per call
//
// Complexity bounds: every predicate is O(1); converters are O(1);
// table scans in other modules are bounded by the capacities above.
// No operation allocates; every function is total over its domain.
module mncs.jit.types.v1;

use mncs.core.logic.v1 as logic;

// Execution providers. Reference and Cranelift are implemented;
// LLVM and Native exist as first-class future provider classes so
// policy code can name them without faking execution (selection of an
// unimplemented provider is an explicit deferred verdict, never a
// silent substitution).
enum Provider { Reference, Cranelift, Llvm, Native }

// Provider-neutral artifact lifecycle. Retired is terminal: a retired
// artifact can never become active again, even if it is still alive in
// provider memory (see `mncs.jit.lifecycle.v1`).
enum Lifecycle { Empty, Compiled, Published, Active, Retired }

// Execution tier advisory state. Thresholds are policy parameters at
// the call site, never hard-coded here.
enum Tier { Cold, Warm, Hot }

// What changed about a definition. Only BodyOnly leaves dependents
// untouched; Signature and Contract changes force dependent review.
enum ChangeKind { BodyOnly, Signature, Contract }

// What a dependency edge observes. Call edges break only when the
// used definition's callable behavior changes; Signature edges break
// on signature change; Layout edges break on contract change.
enum DepKind { Call, Signature, Layout }

// Per-dependent invalidation verdict. Unaffected keeps routing;
// ValidRoutesNew keeps the current binding (no recompile) while new
// calls pick up the new generation once published; RequiresRecompile
// marks the dependent binding stale until it is rebuilt.
enum DepVerdict { Unaffected, ValidRoutesNew, RequiresRecompile }

// Logical binding state. Stale bindings never resolve to an artifact;
// Retired bindings belong to a closed session.
enum Validity { Valid, Stale, Retired }

// Workload classes for provider selection. Accelerator has no
// provider yet: selecting for it is an explicit unsupported verdict.
enum Workload { OneShot, Interactive, HotStable, Accelerator }

// Proof/execution metadata carried by every definition and every
// compiled artifact. Generations are session counters, not wall time;
// assumption_bits is an opaque kernel-owned bitmap the JIT compares
// for equality but never interprets.
record ProofRef { semantic_generation: u64, proof_generation: u64, assumption_bits: u64 }

// One source generation of a logical definition. History rows are
// never mutated: redefinition appends a new row.
record Definition {
    logical: u64,
    generation: u64,
    content_hash: u64,
    change_code: u64,
    semantic_generation: u64,
    proof_generation: u64,
    assumption_bits: u64,
    dep_count: u64,
}

// Logical binding: which executable generation of a logical
// definition is currently selected, plus the previous selection for
// explicit rollback when a new generation fails to publish.
record Binding {
    logical: u64,
    generation: u64,
    artifact: u64,
    previous_generation: u64,
    previous_artifact: u64,
    state_code: u64,
    stale_reason: u64,
}

// One compiled executable generation. `code` is the MNCS-assigned
// artifact identity; provider memory is keyed by it host-side.
// `publish_seq` orders publications deterministically.
record Executable {
    code: u64,
    logical: u64,
    generation: u64,
    provider_code: u64,
    lifecycle_code: u64,
    semantic_generation: u64,
    proof_generation: u64,
    assumption_bits: u64,
    compile_ms: u64,
    publish_seq: u64,
}

// Dependency edge: `user` depends on `used` through `kind_code`.
record DepEdge { user: u64, used: u64, kind_code: u64 }

// Persistent JIT session value. The host threads this value between
// calls (the `task` pattern); the language never hides state in an
// ambient store. `closed` freezes the session: every mutating entry
// point rejects a closed session with the value unchanged.
record Session {
    semantic_generation: u64,
    proof_generation: u64,
    next_logical: u64,
    next_generation: u64,
    next_artifact: u64,
    publish_seq: u64,
    closed: bool,
    defs: [Definition; 8],
    def_count: u64,
    bindings: [Binding; 8],
    binding_count: u64,
    artifacts: [Executable; 16],
    artifact_count: u64,
    edges: [DepEdge; 16],
    edge_count: u64,
}

// --- Provider converters and predicates ---

fn provider_of(code: u64) -> (result: Provider) {
    if code == 1 {
        return Provider.Cranelift;
    }
    if code == 2 {
        return Provider.Llvm;
    }
    if code == 3 {
        return Provider.Native;
    }
    return Provider.Reference;
}

fn provider_code(p: Provider) -> (result: u64) {
    return match p {
        Reference => 0,
        Cranelift => 1,
        Llvm => 2,
        Native => 3,
    };
}

fn provider_is_known(code: u64) -> (result: bool) {
    return code <= 3;
}

// Only Reference and Cranelift execute today. LLVM and Native are
// named future classes; routing to them must go through the plan
// layer's explicit deferred verdict.
fn provider_is_implemented(code: u64) -> (result: bool) {
    return code == 0 || code == 1;
}

fn provider_is_native(code: u64) -> (result: bool) {
    return code == 1 || code == 2 || code == 3;
}

// --- Lifecycle converters and predicates ---

fn lifecycle_of(code: u64) -> (result: Lifecycle) {
    if code == 1 {
        return Lifecycle.Compiled;
    }
    if code == 2 {
        return Lifecycle.Published;
    }
    if code == 3 {
        return Lifecycle.Active;
    }
    if code == 4 {
        return Lifecycle.Retired;
    }
    return Lifecycle.Empty;
}

fn lifecycle_code(l: Lifecycle) -> (result: u64) {
    return match l {
        Empty => 0,
        Compiled => 1,
        Published => 2,
        Active => 3,
        Retired => 4,
    };
}

fn lifecycle_is_known(code: u64) -> (result: bool) {
    return code <= 4;
}

// Live artifacts occupy provider memory and may still be published
// or invoked; only Active artifacts serve new calls through bindings.
fn lifecycle_is_live(code: u64) -> (result: bool) {
    return code == 1 || code == 2 || code == 3;
}

fn lifecycle_is_terminal(code: u64) -> (result: bool) {
    return code == 4;
}

// --- Tier converters ---

fn tier_of(code: u64) -> (result: Tier) {
    if code == 1 {
        return Tier.Warm;
    }
    if code == 2 {
        return Tier.Hot;
    }
    return Tier.Cold;
}

fn tier_code(t: Tier) -> (result: u64) {
    return match t {
        Cold => 0,
        Warm => 1,
        Hot => 2,
    };
}

fn tier_is_known(code: u64) -> (result: bool) {
    return code <= 2;
}

// --- Change-kind converters and policy ---

fn change_of(code: u64) -> (result: ChangeKind) {
    if code == 1 {
        return ChangeKind.Signature;
    }
    if code == 2 {
        return ChangeKind.Contract;
    }
    return ChangeKind.BodyOnly;
}

fn change_code(c: ChangeKind) -> (result: u64) {
    return match c {
        BodyOnly => 0,
        Signature => 1,
        Contract => 2,
    };
}

fn change_is_known(code: u64) -> (result: bool) {
    return code <= 2;
}

// Only body-only changes leave dependents untouched. Signature and
// contract changes force dependent review; the edge kind then decides
// between ValidRoutesNew and RequiresRecompile.
fn change_forces_dependent_review(code: u64) -> (result: bool) {
    return code == 1 || code == 2;
}

// --- Dependency-kind converters ---

fn dep_kind_of(code: u64) -> (result: DepKind) {
    if code == 1 {
        return DepKind.Signature;
    }
    if code == 2 {
        return DepKind.Layout;
    }
    return DepKind.Call;
}

fn dep_kind_code(k: DepKind) -> (result: u64) {
    return match k {
        Call => 0,
        Signature => 1,
        Layout => 2,
    };
}

fn dep_kind_is_known(code: u64) -> (result: bool) {
    return code <= 2;
}

// --- Verdict and validity converters ---

fn verdict_code(v: DepVerdict) -> (result: u64) {
    return match v {
        Unaffected => 0,
        ValidRoutesNew => 1,
        RequiresRecompile => 2,
    };
}

fn verdict_requires_recompile(code: u64) -> (result: bool) {
    return code == 2;
}

fn validity_of(code: u64) -> (result: Validity) {
    if code == 1 {
        return Validity.Stale;
    }
    if code == 2 {
        return Validity.Retired;
    }
    return Validity.Valid;
}

fn validity_code(v: Validity) -> (result: u64) {
    return match v {
        Valid => 0,
        Stale => 1,
        Retired => 2,
    };
}

fn validity_is_known(code: u64) -> (result: bool) {
    return code <= 2;
}

// --- Workload converters ---

fn workload_of(code: u64) -> (result: Workload) {
    if code == 1 {
        return Workload.Interactive;
    }
    if code == 2 {
        return Workload.HotStable;
    }
    if code == 3 {
        return Workload.Accelerator;
    }
    return Workload.OneShot;
}

fn workload_code(w: Workload) -> (result: u64) {
    return match w {
        OneShot => 0,
        Interactive => 1,
        HotStable => 2,
        Accelerator => 3,
    };
}

fn workload_is_known(code: u64) -> (result: bool) {
    return code <= 3;
}

// --- Executable entry points (scalar shapes for backend corpora) ---

// Provider table: implemented and native bits over codes 0..3 with
// weights 8/4/2/1. Implemented = codes {0, 1} -> 12; native =
// codes {1, 2, 3} -> 7; packed 12 *% 16 +% 7 = 199.
fn candidate_provider_table() -> (result: i64) {
    let impl_pack: u64 = select(provider_is_implemented(0), 8, 0) as u64
        +% select(provider_is_implemented(1), 4, 0) as u64
        +% select(provider_is_implemented(2), 2, 0) as u64
        +% select(provider_is_implemented(3), 1, 0) as u64;
    let nat_pack: u64 = select(provider_is_native(0), 8, 0) as u64
        +% select(provider_is_native(1), 4, 0) as u64
        +% select(provider_is_native(2), 2, 0) as u64
        +% select(provider_is_native(3), 1, 0) as u64;
    return impl_pack as i64 *% 16 +% nat_pack as i64;
}

// Lifecycle table: live bits over codes 0..4 (Compiled/Published/
// Active = 01110 = 14) plus terminal bit for Retired (1): 14*2+1=29.
fn candidate_lifecycle_table() -> (result: i64) {
    let live: u64 = select(lifecycle_is_live(0), 16, 0) as u64
        +% select(lifecycle_is_live(1), 8, 0) as u64
        +% select(lifecycle_is_live(2), 4, 0) as u64
        +% select(lifecycle_is_live(3), 2, 0) as u64
        +% select(lifecycle_is_live(4), 1, 0) as u64;
    return live as i64 *% 2 +% select(lifecycle_is_terminal(4), 1, 0) as i64;
}

// Change policy: review bits over BodyOnly/Signature/Contract
// (011 = 3) and recompile-require bits (RequiresRecompile is code 2:
// verdict_requires_recompile over 0/1/2 = 001 = 1): 3*4+1 = 13.
fn candidate_change_policy() -> (result: i64) {
    let review: u64 = select(change_forces_dependent_review(0), 4, 0) as u64
        +% select(change_forces_dependent_review(1), 2, 0) as u64
        +% select(change_forces_dependent_review(2), 1, 0) as u64;
    let recomp: u64 = select(verdict_requires_recompile(0), 4, 0) as u64
        +% select(verdict_requires_recompile(1), 2, 0) as u64
        +% select(verdict_requires_recompile(2), 1, 0) as u64;
    return review as i64 *% 4 +% recomp as i64;
}

// Converter round-trips: every *_of(*_code(x)) is the identity over
// the known domain. Pack of eight round-trip bits, all set: 255.
fn candidate_codes_roundtrip() -> (result: i64) {
    let ok_provider: bool = provider_code(provider_of(0)) == 0
        && provider_code(provider_of(1)) == 1
        && provider_code(provider_of(2)) == 2
        && provider_code(provider_of(3)) == 3;
    let ok_lifecycle: bool = lifecycle_code(lifecycle_of(0)) == 0
        && lifecycle_code(lifecycle_of(4)) == 4;
    let ok_tier: bool = tier_code(tier_of(0)) == 0 && tier_code(tier_of(2)) == 2;
    let ok_change: bool = change_code(change_of(0)) == 0 && change_code(change_of(2)) == 2;
    let ok_dep: bool = dep_kind_code(dep_kind_of(0)) == 0 && dep_kind_code(dep_kind_of(2)) == 2;
    let ok_validity: bool = validity_code(validity_of(1)) == 1;
    let ok_workload: bool = workload_code(workload_of(3)) == 3;
    let ok_known: bool = provider_is_known(3)
        && logic.bool_not(provider_is_known(4))
        && lifecycle_is_known(4)
        && logic.bool_not(lifecycle_is_known(5))
        && workload_is_known(0)
        && logic.bool_not(workload_is_known(9));
    let pack: u64 = select(ok_provider, 128, 0) as u64
        +% select(ok_lifecycle, 64, 0) as u64
        +% select(ok_tier, 32, 0) as u64
        +% select(ok_change, 16, 0) as u64
        +% select(ok_dep, 8, 0) as u64
        +% select(ok_validity, 4, 0) as u64
        +% select(ok_workload, 2, 0) as u64
        +% select(ok_known, 1, 0) as u64;
    return pack as i64;
}

mncs 0.8;

// mncs.std.ansi.v1 — bounded ANSI/VT semantic parsing.
//
// This module owns terminal protocol meaning and has no dependency on a TUI
// framework. It emits generic terminal events; an application adapter maps
// those events into its own event vocabulary. The bounded entry point accepts
// at most ten bytes, enough for the common one- and two-digit CSI forms used
// by this vertical slice. Any incomplete, malformed, or unsupported sequence
// is Unknown rather than an inferred stronger event.
module mncs.std.ansi.v1;

use mncs.core.bytes.v1;

enum AnsiEvent {
    Character { codepoint: i64 },
    Escape,
    Arrow { direction: i64, modifiers: i64 },
    Focus { gained: bool },
    PasteStart,
    PasteEnd,
    Mouse { column: i64, row: i64, button: i64, pressed: bool },
    Resize { columns: i64, rows: i64 },
    Unknown { raw: i64 }
}

record ParserState { b0: byte, b1: byte, b2: byte, b3: byte, b4: byte, b5: byte, b6: byte, b7: byte, b8: byte, b9: byte, length: i64 }
record ParseResult { event: AnsiEvent, state: ParserState, complete: bool }

fn parser_init() -> (result: ParserState) {
    return ParserState { b0: 0, b1: 0, b2: 0, b3: 0, b4: 0, b5: 0, b6: 0, b7: 0, b8: 0, b9: 0, length: 0 };
}

fn byte_value(value: byte) -> (result: i64) {
    return value as i64;
}

fn one_digit(value: byte) -> (result: i64) {
    return digit_value(value);
}

fn two_digits(high: byte, low: byte) -> (result: i64) {
    return (one_digit(high) *% 10) +% one_digit(low);
}

fn unknown(raw: i64) -> (result: AnsiEvent) {
    return AnsiEvent.Unknown { raw: raw };
}

fn sequence_event(length: i64, b0: byte, b1: byte, b2: byte, b3: byte, b4: byte, b5: byte, b6: byte, b7: byte, b8: byte, b9: byte) -> (result: AnsiEvent) {
    let v0: i64 = byte_value(b0);
    let v1: i64 = byte_value(b1);
    let v2: i64 = byte_value(b2);
    let v3: i64 = byte_value(b3);
    let v4: i64 = byte_value(b4);
    let v5: i64 = byte_value(b5);
    let v6: i64 = byte_value(b6);
    let v7: i64 = byte_value(b7);
    let v8: i64 = byte_value(b8);
    let v9: i64 = byte_value(b9);
    if length == 0 {
        return unknown(0);
    }
    if length == 1 {
        if v0 >= 32 && v0 <= 126 {
            return AnsiEvent.Character { codepoint: v0 };
        }
        if v0 == 27 {
            return AnsiEvent.Escape;
        }
        return unknown(v0);
    }
    if length == 3 && v0 == 27 && v1 == 91 {
        if v2 == 65 {
            return AnsiEvent.Arrow { direction: 0, modifiers: 0 };
        }
        if v2 == 66 {
            return AnsiEvent.Arrow { direction: 1, modifiers: 0 };
        }
        if v2 == 67 {
            return AnsiEvent.Arrow { direction: 2, modifiers: 0 };
        }
        if v2 == 68 {
            return AnsiEvent.Arrow { direction: 3, modifiers: 0 };
        }
        if v2 == 73 {
            return AnsiEvent.Focus { gained: true };
        }
        if v2 == 79 {
            return AnsiEvent.Focus { gained: false };
        }
    }
    if length == 6 && v0 == 27 && v1 == 91 && v2 == 50 && v3 == 48 && v4 == 48 && v5 == 126 {
        return AnsiEvent.PasteStart;
    }
    if length == 6 && v0 == 27 && v1 == 91 && v2 == 50 && v3 == 48 && v4 == 49 && v5 == 126 {
        return AnsiEvent.PasteEnd;
    }
    // X10 mouse reporting: CSI M Cb Cx Cy, with coordinates biased by 32.
    if length == 6 && v0 == 27 && v1 == 91 && v2 == 77 && v3 >= 32 && v4 >= 32 && v5 >= 32 {
        let button_code: i64 = (v3 - 32) % 4;
        return AnsiEvent.Mouse { column: v4 - 32, row: v5 - 32, button: button_code, pressed: (v3 - 32) < 3 };
    }
    // CSI 8;R;Ct with one digit dimensions.
    if length == 8 && v0 == 27 && v1 == 91 && v2 == 56 && v3 == 59 && v5 == 59 && v7 == 116 && is_digit(b4) && is_digit(b6) {
        return AnsiEvent.Resize { columns: one_digit(b6), rows: one_digit(b4) };
    }
    // CSI 8;RR;CCt with two digit dimensions.
    if length == 10 && v0 == 27 && v1 == 91 && v2 == 56 && v3 == 59 && v6 == 59 && v9 == 116 && is_digit(b4) && is_digit(b5) && is_digit(b7) && is_digit(b8) {
        return AnsiEvent.Resize { columns: two_digits(b7, b8), rows: two_digits(b4, b5) };
    }
    return unknown(v0);
}

fn parse_sequence(length: i64, b0: byte, b1: byte, b2: byte, b3: byte, b4: byte, b5: byte, b6: byte, b7: byte, b8: byte, b9: byte) -> (result: AnsiEvent) {
    let bounded_length: i64 = select(length < 0, 0, select(length > 10, 10, length));
    return sequence_event(bounded_length, b0, b1, b2, b3, b4, b5, b6, b7, b8, b9);
}

fn append(state: ParserState, value: byte) -> (result: ParserState) {
    if state.length == 0 {
        return ParserState { b0: value, b1: state.b1, b2: state.b2, b3: state.b3, b4: state.b4, b5: state.b5, b6: state.b6, b7: state.b7, b8: state.b8, b9: state.b9, length: 1 };
    }
    if state.length == 1 {
        return ParserState { b0: state.b0, b1: value, b2: state.b2, b3: state.b3, b4: state.b4, b5: state.b5, b6: state.b6, b7: state.b7, b8: state.b8, b9: state.b9, length: 2 };
    }
    if state.length == 2 {
        return ParserState { b0: state.b0, b1: state.b1, b2: value, b3: state.b3, b4: state.b4, b5: state.b5, b6: state.b6, b7: state.b7, b8: state.b8, b9: state.b9, length: 3 };
    }
    if state.length == 3 {
        return ParserState { b0: state.b0, b1: state.b1, b2: state.b2, b3: value, b4: state.b4, b5: state.b5, b6: state.b6, b7: state.b7, b8: state.b8, b9: state.b9, length: 4 };
    }
    if state.length == 4 {
        return ParserState { b0: state.b0, b1: state.b1, b2: state.b2, b3: state.b3, b4: value, b5: state.b5, b6: state.b6, b7: state.b7, b8: state.b8, b9: state.b9, length: 5 };
    }
    if state.length == 5 {
        return ParserState { b0: state.b0, b1: state.b1, b2: state.b2, b3: state.b3, b4: state.b4, b5: value, b6: state.b6, b7: state.b7, b8: state.b8, b9: state.b9, length: 6 };
    }
    if state.length == 6 {
        return ParserState { b0: state.b0, b1: state.b1, b2: state.b2, b3: state.b3, b4: state.b4, b5: state.b5, b6: value, b7: state.b7, b8: state.b8, b9: state.b9, length: 7 };
    }
    if state.length == 7 {
        return ParserState { b0: state.b0, b1: state.b1, b2: state.b2, b3: state.b3, b4: state.b4, b5: state.b5, b6: state.b6, b7: value, b8: state.b8, b9: state.b9, length: 8 };
    }
    if state.length == 8 {
        return ParserState { b0: state.b0, b1: state.b1, b2: state.b2, b3: state.b3, b4: state.b4, b5: state.b5, b6: state.b6, b7: state.b7, b8: value, b9: state.b9, length: 9 };
    }
    return ParserState { b0: state.b0, b1: state.b1, b2: state.b2, b3: state.b3, b4: state.b4, b5: state.b5, b6: state.b6, b7: state.b7, b8: state.b8, b9: value, length: 10 };
}

fn parser_feed(state: ParserState, value: byte) -> (result: ParseResult) {
    let appended: ParserState = append(state, value);
    let first: i64 = byte_value(appended.b0);
    if state.length == 0 && first >= 32 && first <= 126 {
        return ParseResult { event: AnsiEvent.Character { codepoint: first }, state: parser_init(), complete: true };
    }
    if state.length == 0 && first != 27 {
        return ParseResult { event: unknown(first), state: parser_init(), complete: true };
    }
    // Keep ESC pending: the following `[` may begin a CSI sequence. A host
    // that wants a standalone Escape can use parse_sequence(1, 27, ...).
    if appended.length == 1 && first == 27 {
        return ParseResult { event: unknown(0), state: appended, complete: false };
    }
    let event: AnsiEvent = sequence_event(appended.length, appended.b0, appended.b1, appended.b2, appended.b3, appended.b4, appended.b5, appended.b6, appended.b7, appended.b8, appended.b9);
    let complete: bool = match event {
        Character { codepoint } => true,
        Escape => appended.length == 1,
        Arrow { direction, modifiers } => true,
        Focus { gained } => true,
        PasteStart => true,
        PasteEnd => true,
        Mouse { column, row, button, pressed } => true,
        Resize { columns, rows } => true,
        Unknown { raw } => appended.length >= 3,
    };
    if complete {
        return ParseResult { event: event, state: parser_init(), complete: true };
    }
    return ParseResult { event: unknown(0), state: appended, complete: false };
}

fn ansi_event_is_unknown(event: AnsiEvent) -> (result: bool) {
    return match event {
        Unknown { raw } => true,
        Character { codepoint } => false,
        Escape => false,
        Arrow { direction, modifiers } => false,
        Focus { gained } => false,
        PasteStart => false,
        PasteEnd => false,
        Mouse { column, row, button, pressed } => false,
        Resize { columns, rows } => false,
    };
}

mncs 0.13;

// mncs.std.channel — deterministic bounded-channel contracts.
//
// A Channel is a bounded FIFO with explicit producer accounting and a
// close-once contract, expressed as total bounded functions over explicit
// values. It is the SOURCE-SEMANTICS half of MNCS producer/consumer
// communication (RFC 0010): capacity, backpressure, close semantics,
// deterministic shutdown, and producer/consumer causality are all decided
// here without threads, blocking, or a scheduler.
//
// Blocking is NOT in this module: `send` reports backpressure as data
// (`blocked`, never a block) and `recv` reports emptiness as data
// (`kind == 1`, never a wait). A host or runtime realization loops on
// those verdicts; cancellation safety for a blocked party is then the
// realization checking its cancel flag between retries, exactly like the
// `mncs-index` drain protocol this contract is meant to replace. What the
// language owns — and what this module pins on every backend — is the
// contract a realization must honor.
//
// The one clear close contract:
// - `new(capacity, producers)` registers how many producers must report
//   done before the channel may close.
// - `producer_done` records one finished producer.
// - `close` is accepted exactly once, and only when every registered
//   producer is done (`done == producers`).
// - `recv` reports `kind == 2` (closed) if and only if the channel is
//   closed AND fully drained. Close is therefore observed exactly once
//   per drain, with no sentinel value convention: DATA/EMPTY/CLOSED are
//   carried in `kind`, never in `value`.
module mncs.std.channel.v1;

use mncs.core.logic.v1 as logic;

record Channel {
    buf: [u64; 8],
    count: u64,
    capacity: u64,
    producers: u64,
    done: u64,
    closed: bool
}

record SendOut { channel: Channel, accepted: bool, blocked: bool }

record RecvOut { channel: Channel, kind: u64, value: u64 }

record CloseOut { channel: Channel, accepted: bool }

record DoneOut { channel: Channel, accepted: bool }

// Open a channel holding up to `capacity` items (clamped 1..=8) from
// exactly `producers` producers (clamped 0..=8).
fn new(capacity: u64, producers: u64) -> (result: Channel) {
    let cap: u64 = select(capacity <= 8, capacity, 8);
    let clamped: u64 = select(cap >= 1, cap, 1);
    let who: u64 = select(producers <= 8, producers, 8);
    return Channel {
        buf: [0; 8],
        count: 0,
        capacity: clamped,
        producers: who,
        done: 0,
        closed: false
    };
}

// Enqueue one item. Full (but open) reports `blocked` — backpressure as
// data. Closed rejects. Neither traps.
fn send(ch: Channel, value: u64) -> (result: SendOut) {
    let full: bool = ch.count >= ch.capacity;
    let accepted: bool = logic.bool_not(ch.closed) && logic.bool_not(full);
    let blocked: bool = logic.bool_not(ch.closed) && full;
    let slot: u64 = select(accepted, ch.count, 0);
    let grown: Channel = Channel { ..ch, buf: replace(ch.buf, slot, value), count: ch.count +% 1 };
    return SendOut { channel: select(accepted, grown, ch), accepted: accepted, blocked: blocked };
}

record ShiftFold { buf: [u64; 8] }

// Dequeue one item in FIFO order. `kind` is 0 (data), 1 (open but empty:
// retry), or 2 (closed and drained: close observed). Values are never
// sentinel-bearing: `value` is meaningful only when `kind == 0`.
fn recv(ch: Channel) -> (result: RecvOut) {
    let has_data: bool = ch.count > 0;
    let drained_close: bool = ch.closed && logic.bool_not(has_data);
    let kind: u64 = select(has_data, 0, select(drained_close, 2, 1));
    let head: u64 = ch.buf[0];
    let seed: ShiftFold = ShiftFold { buf: ch.buf };
    iterate i over ch.buf carrying st: ShiftFold = seed {
        let src: u64 = select(i +% 1 < 8, i +% 1, 0);
        let carry: bool = i +% 1 < ch.count;
        let moved: u64 = select(carry, st.buf[src], st.buf[i]);
        next st = ShiftFold { buf: replace(st.buf, i, moved) };
    }
    let shifted: Channel = Channel { ..ch, buf: st.buf, count: ch.count -% 1 };
    return RecvOut { channel: select(has_data, shifted, ch), kind: kind, value: select(has_data, head, 0) };
}

// Record one finished producer. Rejected once all registered producers
// are done (over-reporting is observable, not fatal).
fn producer_done(ch: Channel) -> (result: DoneOut) {
    let ok: bool = logic.bool_not(ch.closed) && ch.done < ch.producers;
    let advanced: Channel = Channel { ..ch, done: ch.done +% 1 };
    return DoneOut { channel: select(ok, advanced, ch), accepted: ok };
}

// Close the channel: accepted exactly once, and only after every
// registered producer reported done. A rejected close leaves the channel
// unchanged, so an early close can never smuggle the channel shut.
fn close(ch: Channel) -> (result: CloseOut) {
    let ok: bool = logic.bool_not(ch.closed) && ch.done == ch.producers;
    if ok {
        return CloseOut { channel: Channel { ..ch, closed: true }, accepted: true };
    } else {
    }
    return CloseOut { channel: ch, accepted: false };
}

// --- Executable entry points (scalar shapes for backend corpora) ---

// Channel test: two producers, one consumer, capacity 2 forcing
// backpressure. Eight items flow FIFO (sum 36, order exact); the third
// send while full reports blocked; close is accepted once after both
// producers are done; the drained close is observed as kind 2; a second
// close is rejected. Packs to 361121.
fn candidate_channel_flow() -> (result: i64) {
    let c0: Channel = new(2, 2);
    // Producer A fills the channel.
    let s1: SendOut = send(c0, 1);
    let s2: SendOut = send(s1.channel, 2);
    // Producer A hits backpressure on the third send.
    let s3: SendOut = send(s2.channel, 3);
    let blocked: bool = s3.blocked && logic.bool_not(s3.accepted);
    // Consumer drains one, producer A's item fits.
    let r1: RecvOut = recv(s2.channel);
    let s4: SendOut = send(r1.channel, 3);
    // Consumer drains the next two in order.
    let r2: RecvOut = recv(s4.channel);
    let r3: RecvOut = recv(r2.channel);
    // Producer B fills while the consumer keeps draining.
    let s5: SendOut = send(r3.channel, 4);
    let s6: SendOut = send(s5.channel, 5);
    let r4: RecvOut = recv(s6.channel);
    let s7: SendOut = send(r4.channel, 6);
    let r5: RecvOut = recv(s7.channel);
    let r6: RecvOut = recv(r5.channel);
    let s8: SendOut = send(r6.channel, 7);
    let s9: SendOut = send(s8.channel, 8);
    let r7: RecvOut = recv(s9.channel);
    let r8: RecvOut = recv(r7.channel);
    // Both producers report done; the owner closes exactly once.
    let d1: DoneOut = producer_done(r8.channel);
    let d2: DoneOut = producer_done(d1.channel);
    let shut: CloseOut = close(d2.channel);
    let empty: RecvOut = recv(shut.channel);
    let again: CloseOut = close(empty.channel);
    let ordered: bool = r1.value == 1 && r2.value == 2 && r3.value == 3 && r4.value == 4 && r5.value == 5 && r6.value == 6 && r7.value == 7 && r8.value == 8;
    let sum: u64 = r1.value +% r2.value +% r3.value +% r4.value +% r5.value +% r6.value +% r7.value +% r8.value;
    let kinds: bool = r1.kind == 0 && r8.kind == 0 && empty.kind == 2;
    let ok: bool = s1.accepted && s2.accepted && blocked && s4.accepted && s5.accepted && s6.accepted && s7.accepted && s8.accepted && s9.accepted && d1.accepted && d2.accepted && shut.accepted && kinds && logic.bool_not(again.accepted);
    return select(ok && ordered, (sum as i64) * 10000 + 1000 + 100 + 20 + 1, 0 - 1);
}

// Empty/close-boundary test: recv on an open empty channel reports EMPTY
// (1); close before producers are done is rejected; after the single
// producer is done close is accepted and the drained close reads CLOSED
// (2). Packs to 102.
fn candidate_channel_empty() -> (result: i64) {
    let c0: Channel = new(2, 1);
    let r0: RecvOut = recv(c0);
    let early: CloseOut = close(r0.channel);
    let d1: DoneOut = producer_done(early.channel);
    let shut: CloseOut = close(d1.channel);
    let drained: RecvOut = recv(shut.channel);
    let ok: bool = r0.kind == 1 && logic.bool_not(early.accepted) && d1.accepted && shut.accepted && drained.kind == 2;
    return select(ok, 102, 0 - 1);
}

// Send-after-close test: a closed channel rejects sends and done reports,
// the buffered item still drains first, then the drained close reads
// CLOSED (11002).
fn candidate_send_closed() -> (result: i64) {
    let c0: Channel = new(1, 0);
    let s1: SendOut = send(c0, 5);
    let shut: CloseOut = close(s1.channel);
    let s2: SendOut = send(shut.channel, 6);
    let r1: RecvOut = recv(s2.channel);
    let r2: RecvOut = recv(r1.channel);
    let dd: DoneOut = producer_done(r2.channel);
    let ok: bool = s1.accepted && shut.accepted && logic.bool_not(s2.accepted) && r1.kind == 0 && r1.value == 5 && r2.kind == 2 && logic.bool_not(dd.accepted);
    return select(ok, 11002, 0 - 1);
}

mncs 0.13;

// mncs.std.chunk — bounded chunk cursors with cross-chunk span identities.
//
// Profile note: this module declares 0.13 (raised from 0.10 for
// INGEST-P-011). Generic specializations are checked against the defining
// module's ceiling, so the capacity-generic scans can only serve 256- and
// ~392-byte stages when the module itself admits bounds past 64.
// Narrow-profile roots are unaffected: each module is admitted under its
// own profile, and the 64-byte entry points keep their exact shapes.
//
// Large inputs arrive as a sequence of ≤64-byte views (one filesystem
// chunk, one grant, one view per call). This module owns the cursor and
// span vocabulary that keeps meaning across chunk boundaries without a
// heap String: a Span names (chunk, start, length), cursors advance by
// explicit offsets, and line-boundary scans are total bounded folds.
//
// The 64-byte seams are the contract, not an accident: `find_newline`
// scans one view, `carry_scan` resumes a scan in the next chunk from an
// explicit carry offset, and `span_length_across` measures a line that
// starts in one chunk and ends in another. Hosts feed chunks in order;
// the language decides boundaries, spans, and slices.
module mncs.std.chunk.v1;

use mncs.core.logic.v1 as logic;

// A span of bytes starting at `start` in chunk `chunk`, `length` bytes
// long. Spans never dangle: producers construct them from scanned
// boundaries, and consumers clamp them into the view they read.
record Span { chunk: u64, start: u64, length: u64 }

// A read cursor: the next unread position. `chunk` selects the view,
// `offset` the position inside it.
record Cursor { chunk: u64, offset: u64 }

// Capacity-generic newline scan (INGEST-P-011): one implementation serves
// every stage width (64-, 256-, ~392-byte views). `N` is the static view
// capacity; the live window is still `min(view_length, view.len)` scanned
// from `from`. Total: overlong `from` simply matches nothing.
fn find_newline_generic<N: Nat>(view: [byte; up_to N], view_length: u64, from: u64) -> (result: i64) {
    let vlen: u64 = select(view_length <= view.len, view_length, view.len);
    iterate i over view carrying found: i64 = 0 - 1 {
        let live: bool = i < vlen && i >= from;
        let hit: bool = live && view[i] == 10;
        next found = select(found == 0 - 1 && hit, i as i64, found);
    }
    return found;
}

// Index of the first `\n` at or after `from` in the view's live window,
// or -1 when the window holds no newline. The 64-byte historical shape is
// preserved exactly; it delegates to the generic scan.
fn find_newline(view: [byte; up_to 64], view_length: u64, from: u64) -> (result: i64) {
    return find_newline_generic<64>(view, view_length, from);
}

// Length of the line starting at `from`, excluding the newline: the
// newline index minus `from`, or the rest of the window when no newline
// follows. Callers detect an unterminated tail (the line may continue in
// the next chunk) by comparing `from + length` against the view length.
fn line_length_generic<N: Nat>(view: [byte; up_to N], view_length: u64, from: u64) -> (result: u64) {
    let vlen: u64 = select(view_length <= view.len, view_length, view.len);
    let start: u64 = select(from <= vlen, from, vlen);
    let end: i64 = find_newline_generic<N>(view, view_length, start);
    return select(end == 0 - 1, vlen -% start, (end as u64) -% start);
}

fn line_length(view: [byte; up_to 64], view_length: u64, from: u64) -> (result: u64) {
    return line_length_generic<64>(view, view_length, from);
}

// Advance a cursor past one line: the span of the line content plus the
// cursor at the next line start (past the newline when one was found).
// Capacity-generic (INGEST-P-011); the 64-byte `next_line` delegates.
record LineStep { span: Span, after: Cursor, terminated: bool }

fn next_line_generic<N: Nat>(view: [byte; up_to N], view_length: u64, cursor: Cursor) -> (result: LineStep) {
    let vlen: u64 = select(view_length <= view.len, view_length, view.len);
    let start: u64 = select(cursor.offset <= vlen, cursor.offset, vlen);
    let length: u64 = line_length_generic<N>(view, view_length, start);
    let end: u64 = start +% length;
    let terminated: bool = end < vlen;
    let after: u64 = select(terminated, end +% 1, end);
    return LineStep {
        span: Span { chunk: cursor.chunk, start: start, length: length },
        after: Cursor { chunk: cursor.chunk, offset: after },
        terminated: terminated
    };
}

fn next_line(view: [byte; up_to 64], view_length: u64, cursor: Cursor) -> (result: LineStep) {
    return next_line_generic<64>(view, view_length, cursor);
}

// Measure a line that starts in an earlier chunk: `prefix_length` bytes
// were already observed (the unterminated tail), and this view holds the
// rest up to its first newline (or the whole view when unterminated).
// Returns the total line length across both chunks plus whether this
// chunk terminated it.
record JoinedLine { total_length: u64, terminated: bool }

fn continue_line_generic<N: Nat>(view: [byte; up_to N], view_length: u64, prefix_length: u64) -> (result: JoinedLine) {
    let end: i64 = find_newline_generic<N>(view, view_length, 0);
    let terminated: bool = logic.bool_not(end == 0 - 1);
    let tail: u64 = select(terminated, end as u64, select(view_length <= view.len, view_length, view.len));
    return JoinedLine { total_length: prefix_length +% tail, terminated: terminated };
}

fn continue_line(view: [byte; up_to 64], view_length: u64, prefix_length: u64) -> (result: JoinedLine) {
    return continue_line_generic<64>(view, view_length, prefix_length);
}

// --- Executable entry points (scalar shapes for backend corpora) ---

// Newline scan: "ab\ncd" holds its newline at index 2; scanning from 3
// finds none. Packs to 2 * 10 + 1 (found-flag) = 21... precisely:
// first * 100 + (second == -1) packs 200 + 1 = 201.
fn candidate_find_newline(view: [byte; up_to 64], view_length: u64) -> (result: i64) {
    let first: i64 = find_newline(view, view_length, 0);
    let second: i64 = find_newline(view, view_length, 3);
    return first * 100 + select(second == 0 - 1, 1, 0);
}

// Single-chunk line step: "ab\ncd" from 0 spans (0, 2), terminates, and
// resumes at 3. Packs start * 10000 + length * 1000 + next * 10 + term.
fn candidate_next_line(view: [byte; up_to 64], view_length: u64) -> (result: i64) {
    let step: LineStep = next_line(view, view_length, Cursor { chunk: 0, offset: 0 });
    return step.span.start as i64 * 10000 + step.span.length as i64 * 1000 + step.after.offset as i64 * 10 + select(step.terminated, 1, 0);
}

// Cross-chunk line: a 60-byte prefix continues into "ef\n..."; the
// joined length is 62 and the line terminates here. Packs 62 * 10 + 1.
fn candidate_continue_line(view: [byte; up_to 64], view_length: u64, prefix_length: u64) -> (result: i64) {
    let joined: JoinedLine = continue_line(view, view_length, prefix_length);
    return joined.total_length as i64 * 10 + select(joined.terminated, 1, 0);
}

// NOTE (INGEST-P-011): 256-/392-byte stage entry points live in
// `examples/source/pressure-wide-stage-scans.mncs`, not here: this module
// stays width-agnostic while the probe example owns the width-specific
// cross-backend proof.

mncs 0.10;

// mncs.std.clock — relational wall-clock comparisons over u64 epoch
// milliseconds (HARNESS-PRESSURE-005).
//
// Time enters MNCS only through the `clock_read()` intrinsic, realized by
// the executor from its own clock under an explicit `--grant-time`
// capability. That observation is wall time, not a monotonic tick: hosts
// may adjust it, and corpora must never pin absolute values. Every
// function here is therefore relational and total over all u64 pairs:
// callers compare instants with wide margins (freshness windows,
// timeouts), and skew reads as zero age rather than a wrap.
//
// No operation allocates; every function is total. Complexity is O(1).
module mncs.std.clock.v1;

// Elapsed milliseconds from `since` to `now`, floored at zero: a `since`
// in the future (clock skew, cross-host comparison) reads as zero age,
// never a wrap-around.
fn elapsed(since: u64, now: u64) -> (result: u64) {
    return select(now >= since, now -% since, 0);
}

// True when `now` has reached `deadline`. The comparison is inclusive:
// an instant exactly at its deadline has expired.
fn expired(deadline: u64, now: u64) -> (result: bool) {
    return now >= deadline;
}

// True when the observation at `stored` is at most `budget` millis old
// at `now`. Future-dated stores read as zero age (see `elapsed`), so
// skew never reports a fresh observation as stale.
fn fresh_within(stored: u64, now: u64, budget: u64) -> (result: bool) {
    return elapsed(stored, now) <= budget;
}

mncs 0.13;

// mncs.std.encoding — canonical big-endian byte encodings for scalar values.
//
// Profile note: this module declares 0.13 (raised from 0.7 for the
// capacity-generic little-endian readers, INGEST-P-011, which need RFC 0013
// explicit polymorphism, plus a defining-module ceiling past 64 so wide
// stages can specialize them). Narrow-profile roots are unaffected: each
// module is admitted under its own profile, so a 0.7 consumer keeps
// importing `mncs.std.encoding.v1` with unchanged 64-byte entry points.
//
// This is the first portable module in mncs.std: it exists because the
// bounded-data substrate finally makes encoded data expressible without
// faking bytes as integers. Encodings here are canonical by construction:
//
// - fixed field widths, most-significant byte first (big-endian);
// - logical value != runtime representation != serialized encoding; these
//   functions are the explicit boundary between the first and the last;
// - every decode is total over its declared input type because the type
//   itself guarantees the width; no partial failure path exists to hide;
// - the round-trip law below is executable: `decode(encode(v)) == v` is a
//   bounded property any consumer can re-run, not folklore.
//
// Wire-contract versioning (RFC 0027) will wrap this module with schema
// identities once family records need them; the byte layout of v1 functions
// is frozen from this commit forward.
//
// Realization envelope (2026-08): `encode_u32`/`decode_u32` are
// sequence-typed exports and execute on research bytecode, portable WASM,
// C11, LLVM IR, and Cranelift through the canonical cell ABI.
module mncs.std.encoding.v1;

// Big-endian u32 -> four bytes, most significant first. Extraction uses
// division and remainder by exact powers of two so no host endianness or
// shift-width folklore participates in meaning.
fn encode_u32(value: u32) -> (result: [byte; 4]) {
    let b0: byte = (value / 16777216) as byte;
    let rest0: u32 = value % 16777216;
    let b1: byte = (rest0 / 65536) as byte;
    let rest1: u32 = rest0 % 65536;
    let b2: byte = (rest1 / 256) as byte;
    let b3: byte = (rest1 % 256) as byte;
    return [b0, b1, b2, b3];
}

// Four big-endian bytes -> u32. Total by type: four bytes always form a
// valid word, so there is no failure mode.
fn decode_u32(data: [byte; 4]) -> (result: u32) {
    let high: u64 = ((data[0] as u64) *% 16777216)
        + ((data[1] as u64) *% 65536)
        + ((data[2] as u64) *% 256);
    return ((high + (data[3] as u64)) % 4294967296) as u32;
}

// Round-trip law for u32: decode after encode reproduces the input exactly.
fn u32_roundtrip(value: u32) -> (result: bool) {
    let encoded: [byte; 4] = encode_u32(value);
    return decode_u32(encoded) == value;
}

// Canonical three-component semantic version: one byte pair per component,
// big-endian, major first — six bytes total. This layout is the wire
// contract for family version records until RFC 0027 supersedes it.
fn encode_version(major: u16, minor: u16, patch: u16) -> (result: [byte; 6]) {
    let mh: byte = (major / 256) as byte;
    let ml: byte = (major % 256) as byte;
    let nh: byte = (minor / 256) as byte;
    let nl: byte = (minor % 256) as byte;
    let ph: byte = (patch / 256) as byte;
    let pl: byte = (patch % 256) as byte;
    return [mh, ml, nh, nl, ph, pl];
}

// Component decoders. Total by type: each component is exactly two bytes.
fn version_major(data: [byte; 6]) -> (result: u32) {
    return ((data[0] as u32) *% 256) + (data[1] as u32);
}

fn version_minor(data: [byte; 6]) -> (result: u32) {
    return ((data[2] as u32) *% 256) + (data[3] as u32);
}

fn version_patch(data: [byte; 6]) -> (result: u32) {
    return ((data[4] as u32) *% 256) + (data[5] as u32);
}

// Round-trip law for versions: all three components reproduce exactly.
fn version_roundtrip(major: u16, minor: u16, patch: u16) -> (result: bool) {
    let encoded: [byte; 6] = encode_version(major, minor, patch);
    let same: bool = ((version_major(encoded) == (major as u32))
        && (version_minor(encoded) == (minor as u32)))
        && (version_patch(encoded) == (patch as u32));
    return same;
}

// Big-endian u16. Total by type.
fn encode_u16(value: u16) -> (result: [byte; 2]) {
    let high: byte = (value / 256) as byte;
    let low: byte = (value % 256) as byte;
    return [high, low];
}

fn decode_u16(data: [byte; 2]) -> (result: u16) {
    return ((data[0] as u16) *% 256) + (data[1] as u16);
}

fn u16_roundtrip(value: u16) -> (result: bool) {
    let encoded: [byte; 2] = encode_u16(value);
    return decode_u16(encoded) == value;
}

// Big-endian u64. Wrapping multiply/add keep the eight-byte fold total,
// including values whose high bit is set. The round-trip law is the
// unsigned ABI regression: 2^63 must decode as a positive u64.
fn encode_u64(value: u64) -> (result: [byte; 8]) {
    let b0: byte = (value / 72057594037927936) as byte;
    let r0: u64 = value % 72057594037927936;
    let b1: byte = (r0 / 281474976710656) as byte;
    let r1: u64 = r0 % 281474976710656;
    let b2: byte = (r1 / 1099511627776) as byte;
    let r2: u64 = r1 % 1099511627776;
    let b3: byte = (r2 / 4294967296) as byte;
    let r3: u64 = r2 % 4294967296;
    let b4: byte = (r3 / 16777216) as byte;
    let r4: u64 = r3 % 16777216;
    let b5: byte = (r4 / 65536) as byte;
    let r5: u64 = r4 % 65536;
    let b6: byte = (r5 / 256) as byte;
    let b7: byte = (r5 % 256) as byte;
    return [b0, b1, b2, b3, b4, b5, b6, b7];
}

fn decode_u64(data: [byte; 8]) -> (result: u64) {
    let s0: u64 = (data[0] as u64) *% 72057594037927936;
    let s1: u64 = s0 +% ((data[1] as u64) *% 281474976710656);
    let s2: u64 = s1 +% ((data[2] as u64) *% 1099511627776);
    let s3: u64 = s2 +% ((data[3] as u64) *% 4294967296);
    let s4: u64 = s3 +% ((data[4] as u64) *% 16777216);
    let s5: u64 = s4 +% ((data[5] as u64) *% 65536);
    let s6: u64 = s5 +% ((data[6] as u64) *% 256);
    return s6 +% (data[7] as u64);
}

fn u64_roundtrip(value: u64) -> (result: bool) {
    let encoded: [byte; 8] = encode_u64(value);
    return decode_u64(encoded) == value;
}

// Little-endian readers over bounded views: one reusable reader serves any
// exact window that borrows into the view bound ([byte; 44], [byte; 46],
// [byte; 22], ...), so multi-format wire modules share readers instead of
// duplicating one per width. Reads are partial in the offset: indexing a
// view traps deterministically when offset+width exceeds the runtime
// length, exactly like every other dynamic view index. Callers that need a
// total read must gate the offset against window.len first.
// Capacity-generic little-endian readers (INGEST-P-011): one reusable
// reader serves every stage width (64-, 256-, ~392-byte views). `N` is the
// static view capacity; reads stay partial in the offset exactly like the
// 64-byte originals — indexing past the runtime length traps
// deterministically, and callers needing a total read gate the offset
// against `window.len` first.
fn read_u16_le_generic<N: Nat>(window: [byte; up_to N], offset: u64) -> (result: u16) {
    let lo: u64 = window[offset] as u64;
    let hi: u64 = window[offset +% 1] as u64;
    return (lo +% hi *% 256) as u16;
}

fn read_u16_le(window: [byte; up_to 64], offset: u64) -> (result: u16) {
    return read_u16_le_generic<64>(window, offset);
}

fn read_u32_le_generic<N: Nat>(window: [byte; up_to N], offset: u64) -> (result: u32) {
    let b0: u64 = window[offset] as u64;
    let b1: u64 = window[offset +% 1] as u64;
    let b2: u64 = window[offset +% 2] as u64;
    let b3: u64 = window[offset +% 3] as u64;
    return (b0 +% b1 *% 256 +% b2 *% 65536 +% b3 *% 16777216) as u32;
}

fn read_u32_le(window: [byte; up_to 64], offset: u64) -> (result: u32) {
    return read_u32_le_generic<64>(window, offset);
}

// NOTE (INGEST-P-011): 256-/392-byte stage entry points live in
// `examples/source/pressure-wide-stage-scans.mncs`, not here: this module
// stays width-agnostic while the probe example owns the width-specific
// cross-backend proof.

mncs 0.6;

// mncs.std.fixed — blessed milli-scale decimal scores.
//
// Deterministic fixed-point for scores, thresholds, margins, and sampling
// parameters (temperature/top_p), chosen over IEEE floats for one reason:
// every operation here is exact, total, and backend-identical by
// construction, with no NaN, infinity, signed zero, rounding mode, or
// optimizer legality to specify. The harness semantic-routing pressure
// (HARNESS-PRESSURE-002) needs lane scores in [0, 1], `minimum_score` /
// `minimum_margin` thresholds, and temperature/top_p representation — all
// of which fit milli units with room to spare.
//
// Scale contract: ONE fixed scale, 1/1000, encoded in the `Score` type.
// A Score is an i64 count of milli-units: 0.60 is 600, 0.12 is 120,
// temperature 1.0 is 1000. Hosts encode with round(x * 1000); decoding is
// the inverse. There is no scale parameter to mismatch and no other scale
// in this module.
//
// Exactness and overflow: addition and subtraction saturate at the i64
// bounds with explicit saturating intents (`+|`, `-|`), so overflow is
// visible at the call site and can never wrap into a wrong-sign score.
// Valid domains (milli magnitudes far below 2^63) never saturate; the
// saturation bound is a fail-safe, not a value. Comparison is exact native
// i64 comparison at the call site; min/max/clamp compose from
// `mncs.core.ordering.v1` (`min_i64`, `max_i64`, `clamp_i64`).
//
// Deliberately out of scope: products and quotients. Milli-times-milli
// needs an explicit divide that would carry an honest UNKNOWN obligation
// into every consumer; represent rates and weights as premultiplied millis
// instead. If a future pressure needs scaled multiplication, it extends
// this module with explicit rounding — not a parallel convention.
module mncs.std.fixed.v1;

// A milli-scale decimal value. The scale lives in the type: unwrapping is
// the only way to observe the raw count, and constructing is the only way
// to bless one.
record Score { millis: i64 }

// Bless a milli count as a score. Total: every i64 is a representable
// count; domain policy (e.g. lanes in [0, 1000]) belongs to the caller.
fn score(millis: i64) -> (result: Score) {
    return Score { millis: millis };
}

// Observe the milli count. Explicit: crossing back to raw integers is
// always visible at the call site.
fn millis(value: Score) -> (result: i64) {
    return value.millis;
}

// Same-scale addition with saturating intent. Exact: no rounding exists
// at this scale to choose.
fn add(left: Score, right: Score) -> (result: Score) {
    return Score { millis: left.millis +| right.millis };
}

// Same-scale subtraction with saturating intent. Margins are the
// canonical use: `sub(selected, runner_up)` is exact and total.
fn sub(left: Score, right: Score) -> (result: Score) {
    return Score { millis: left.millis -| right.millis };
}

// Clamp a score into a closed milli interval. Comparison-only, hence
// obligation-free like the ordering kernels it mirrors.
fn clamp_score(value: Score, lo: Score, hi: Score) -> (result: Score) {
    if value.millis < lo.millis {
        return lo;
    }
    if value.millis > hi.millis {
        return hi;
    }
    return value;
}

// Executable entry points with concrete shapes for backend corpora.

fn candidate_blend(base_millis: i64, bonus_millis: i64) -> (result: i64) {
    let total: Score = add(score(base_millis), score(bonus_millis));
    return millis(total);
}

fn candidate_margin(selected_millis: i64, runner_up_millis: i64) -> (result: i64) {
    let margin: Score = sub(score(selected_millis), score(runner_up_millis));
    return millis(margin);
}

fn candidate_clamp(value_millis: i64, lo_millis: i64, hi_millis: i64) -> (result: i64) {
    let clamped: Score = clamp_score(score(value_millis), score(lo_millis), score(hi_millis));
    return millis(clamped);
}

mncs 0.10;

// mncs.std.json — bounded JSON recognition.
//
// The scanner is allocation-free and operates on a byte view. It recognizes
// objects, arrays, strings, JSON numbers, true/false/null, whitespace,
// separators, bounded nesting, control-byte rejection, and JSON escapes. Its
// scalar result is deliberately stable for cross-backend experiments:
//   positive  — one complete value; 1_000_000 + objects*1_000 + arrays*10 + strings
//   -1        — bounded input ended before a value was complete
//   <= -101   — malformed input; -100-error is the reported error code
//
// This module validates syntax only. Text escape decoding, general UTF-8
// scalar semantics, and dynamic JSON value trees remain later tranches.
module mncs.std.json.v1;

record ScanState {
    stack: u64,
    depth: u64,
    expect: byte,
    mode: byte,
    number: byte,
    literal: byte,
    position: byte,
    escape: bool,
    unicode: byte,
    valid: bool,
    error: byte,
    objects: u64,
    arrays: u64,
    strings: u64
}

fn is_space(value: byte) -> (result: bool) {
    let n: i64 = value as i64;
    return n == 9 || n == 10 || n == 13 || n == 32;
}

fn is_hex(value: byte) -> (result: bool) {
    let n: i64 = value as i64;
    return (n >= 48 && n <= 57) || (n >= 65 && n <= 70) || (n >= 97 && n <= 102);
}

fn after_value(expect: byte) -> (result: byte) {
    if expect == 0 { return 7; }
    if expect == 3 { return 4; }
    return 6;
}

// Five bits per bounded nesting level: two bits for the container kind and
// three bits for the parent expectation. Twelve levels fit in one u64 word.
fn stack_weight(depth: u64) -> (result: u64) {
    if depth == 0 { return 1; }
    if depth == 1 { return 32; }
    if depth == 2 { return 1024; }
    if depth == 3 { return 32768; }
    if depth == 4 { return 1048576; }
    if depth == 5 { return 33554432; }
    if depth == 6 { return 1073741824; }
    if depth == 7 { return 34359738368; }
    if depth == 8 { return 1099511627776; }
    if depth == 9 { return 35184372088832; }
    if depth == 10 { return 1125899906842624; }
    return 36028797018963968;
}

fn scan_bad(state: ScanState, error: byte) -> (result: ScanState) {
    return ScanState { ..state, valid: false, error: error };
}

fn scan_close_value(state: ScanState) -> (result: ScanState) {
    return ScanState { ..state, mode: 0, expect: after_value(state.expect), position: 0 };
}

fn scan_begin_container(state: ScanState, value: byte) -> (result: ScanState) {
    if state.depth >= 12 { return scan_bad(state, 3); }
    let kind: u64 = select(value == 123, 1, 2);
    let parent: u64 = after_value(state.expect) as u64;
    let entry: u64 = kind +% (parent *% 4);
    let stack: u64 = state.stack +% (entry *% stack_weight(state.depth));
    let depth: u64 = state.depth + 1;
    let expect: byte = select(value == 123, 1, 5);
    let objects: u64 = state.objects + (value == 123) as u64;
    let arrays: u64 = state.arrays + (value == 91) as u64;
    return ScanState { ..state, stack: stack, depth: depth, expect: expect, objects: objects, arrays: arrays };
}

fn scan_end_container(state: ScanState, value: byte) -> (result: ScanState) {
    if state.depth == 0 { return scan_bad(state, 1); }
    let entry: u64 = (state.stack / stack_weight(state.depth - 1)) % 32;
    let kind: byte = (entry % 4) as byte;
    let correct: bool = (value == 125 && kind == 1 && (state.expect == 1 || state.expect == 4))
        || (value == 93 && kind == 2 && (state.expect == 5 || state.expect == 6));
    if correct {
        return ScanState {
            ..state,
            stack: state.stack - entry *% stack_weight(state.depth - 1),
            depth: state.depth - 1,
            expect: (entry / 4) as byte,
            mode: 0
        };
    }
    return scan_bad(state, 1);
}

fn scan_begin_string(state: ScanState) -> (result: ScanState) {
    if state.expect == 1 || state.expect == 8 || state.expect == 0 || state.expect == 3 || state.expect == 5 {
        return ScanState { ..state, mode: 1, escape: false, unicode: 0, position: 0 };
    }
    return scan_bad(state, 1);
}

fn scan_string_step(state: ScanState, value: byte) -> (result: ScanState) {
    if (state.unicode as i64) > 0 {
        if is_hex(value) { return ScanState { ..state, unicode: ((state.unicode as i64) - 1) as byte }; }
        return scan_bad(state, 4);
    }
    if state.escape {
        if value == 117 { return ScanState { ..state, escape: false, unicode: 4 }; }
        if value == 34 || value == 92 || value == 47 || value == 98 || value == 102 || value == 110 || value == 114 || value == 116 {
            return ScanState { ..state, escape: false };
        }
        return scan_bad(state, 4);
    }
    if value == 92 { return ScanState { ..state, escape: true }; }
    if value == 34 {
        if state.expect == 1 || state.expect == 8 {
            return ScanState { ..state, mode: 0, expect: 2, strings: state.strings + 1 };
        }
        return scan_close_value(ScanState { ..state, strings: state.strings + 1 });
    }
    if (value as i64) < 32 { return scan_bad(state, 1); }
    return state;
}

fn scan_number_step(state: ScanState, value: byte) -> (result: ScanState) {
    let n: i64 = value as i64;
    if state.number == 0 {
        if value == 48 { return ScanState { ..state, number: 1 }; }
        if n >= 49 && n <= 57 { return ScanState { ..state, number: 2 }; }
        return scan_bad(state, 5);
    }
    if state.number == 1 {
        if value == 46 { return ScanState { ..state, number: 3 }; }
        if value == 101 || value == 69 { return ScanState { ..state, number: 5 }; }
        if is_space(value) || value == 44 || value == 93 || value == 125 { return scan_number_delimiter(state, value); }
        return scan_bad(state, 5);
    }
    if state.number == 2 {
        if n >= 48 && n <= 57 { return state; }
        if value == 46 { return ScanState { ..state, number: 3 }; }
        if value == 101 || value == 69 { return ScanState { ..state, number: 5 }; }
        if is_space(value) || value == 44 || value == 93 || value == 125 { return scan_number_delimiter(state, value); }
        return scan_bad(state, 5);
    }
    if state.number == 3 {
        if n >= 48 && n <= 57 { return ScanState { ..state, number: 4 }; }
        return scan_bad(state, 5);
    }
    if state.number == 4 {
        if n >= 48 && n <= 57 { return state; }
        if value == 101 || value == 69 { return ScanState { ..state, number: 5 }; }
        if is_space(value) || value == 44 || value == 93 || value == 125 { return scan_number_delimiter(state, value); }
        return scan_bad(state, 5);
    }
    if state.number == 5 {
        if value == 43 || value == 45 { return ScanState { ..state, number: 6 }; }
        if n >= 48 && n <= 57 { return ScanState { ..state, number: 7 }; }
        return scan_bad(state, 5);
    }
    if state.number == 6 {
        if n >= 48 && n <= 57 { return ScanState { ..state, number: 7 }; }
        return scan_bad(state, 5);
    }
    if n >= 48 && n <= 57 { return state; }
    if is_space(value) || value == 44 || value == 93 || value == 125 { return scan_number_delimiter(state, value); }
    return scan_bad(state, 5);
}

fn literal_byte(kind: byte, position: byte) -> (result: byte) {
    if kind == 1 {
        if position == 1 { return 114; }
        if position == 2 { return 117; }
        return 101;
    }
    if kind == 2 {
        if position == 1 { return 97; }
        if position == 2 { return 108; }
        if position == 3 { return 115; }
        return 101;
    }
    if position == 1 { return 117; }
    if position == 2 { return 108; }
    return 108;
}

fn literal_end(kind: byte) -> (result: byte) {
    return select(kind == 2, 5, 4);
}

fn scan_literal_step(state: ScanState, value: byte) -> (result: ScanState) {
    if value != literal_byte(state.literal, state.position) { return scan_bad(state, 5); }
    let position: byte = ((state.position as i64) + 1) as byte;
    if position == literal_end(state.literal) {
        return scan_close_value(ScanState { ..state, position: position });
    }
    return ScanState { ..state, position: position };
}

fn scan_structural(state: ScanState, value: byte) -> (result: ScanState) {
    if is_space(value) { return state; }
    if state.expect == 2 {
        if value == 58 { return ScanState { ..state, expect: 3 }; }
        return scan_bad(state, 1);
    }
    if state.expect == 4 || state.expect == 6 || state.expect == 7 {
        if state.expect == 7 { return scan_bad(state, 1); }
        if value == 44 { return ScanState { ..state, expect: select(state.expect == 4, 8, 5) }; }
        if (state.expect == 4 && value == 125) || (state.expect == 6 && value == 93) {
            return scan_end_container(state, value);
        }
        return scan_bad(state, 1);
    }
    if state.expect == 1 && value == 125 { return scan_end_container(state, value); }
    if state.expect == 5 && value == 93 { return scan_end_container(state, value); }
    if (state.expect == 1 || state.expect == 8) && value == 34 { return scan_begin_string(state); }
    if state.expect == 0 || state.expect == 3 || state.expect == 5 {
        if value == 123 || value == 91 { return scan_begin_container(state, value); }
        if value == 34 { return scan_begin_string(state); }
        if value == 116 { return ScanState { ..state, mode: 3, literal: 1, position: 1 }; }
        if value == 102 { return ScanState { ..state, mode: 3, literal: 2, position: 1 }; }
        if value == 110 { return ScanState { ..state, mode: 3, literal: 3, position: 1 }; }
        if value == 45 { return ScanState { ..state, mode: 2, number: 0 }; }
        if value == 48 { return ScanState { ..state, mode: 2, number: 1 }; }
        if (value as i64) >= 49 && (value as i64) <= 57 { return ScanState { ..state, mode: 2, number: 2 }; }
    }
    return scan_bad(state, 1);
}

// A delimiter terminates a number but still belongs to the surrounding JSON
// grammar. Reprocess it after closing the scalar so commas and container
// terminators advance the parent state instead of being consumed by the
// number recognizer.
fn scan_number_delimiter(state: ScanState, value: byte) -> (result: ScanState) {
    let closed: ScanState = scan_close_value(state);
    if is_space(value) { return closed; }
    return scan_structural(closed, value);
}

fn scan_step(state: ScanState, value: byte) -> (result: ScanState) {
    if state.valid {
        if state.mode == 1 { return scan_string_step(state, value); }
        if state.mode == 2 { return scan_number_step(state, value); }
        if state.mode == 3 { return scan_literal_step(state, value); }
        return scan_structural(state, value);
    }
    return state;
}

fn scan_finish_end(state: ScanState) -> (result: ScanState) {
    if state.mode == 2 && (state.number == 1 || state.number == 2 || state.number == 4 || state.number == 7) {
        return scan_close_value(state);
    }
    return state;
}

fn scan(input: [byte; up_to 64]) -> (result: i64) {
    let start: ScanState = ScanState {
        stack: 0,
        depth: 0,
        expect: 0,
        mode: 0,
        number: 0,
        literal: 0,
        position: 0,
        escape: false,
        unicode: 0,
        valid: true,
        error: 0,
        objects: 0,
        arrays: 0,
        strings: 0
    };
    iterate i over input carrying state: ScanState = start {
        next state = scan_step(state, input[i]);
    }
    let finished: ScanState = scan_finish_end(state);
    let complete: bool = finished.valid && finished.depth == 0 && finished.mode == 0 && finished.expect == 7;
    if complete {
        return 1000000 +% (finished.objects as i64) *% 1000 +% (finished.arrays as i64) *% 10 +% (finished.strings as i64);
    }
    if finished.valid { return 0 - 1; }
    return 0 - (100 + finished.error as i64);
}

