        edges: [Edge { src: 0, dst: 0 }, Edge { src: 0, dst: 0 }, Edge { src: 0, dst: 0 }, Edge { src: 0, dst: 0 }, Edge { src: 0, dst: 0 }, Edge { src: 0, dst: 0 }, Edge { src: 0, dst: 0 }, Edge { src: 0, dst: 0 }, Edge { src: 0, dst: 0 }, Edge { src: 0, dst: 0 }, Edge { src: 0, dst: 0 }, Edge { src: 0, dst: 0 }, Edge { src: 0, dst: 0 }, Edge { src: 0, dst: 0 }, Edge { src: 0, dst: 0 }, Edge { src: 0, dst: 0 }],
