// --- Executable entry points ---

// SHA-256("abc") through init/update/finalize.
fn candidate_sha256_abc(chunk: [byte; up_to 64], chunk_length: u64, k: [u32; 64]) -> (result: [byte; 32]) {
    let s0: DigestState = init();
    let s1: DigestState = update(s0, chunk, chunk_length, k);
    return finalize(s1, k);
}

// SHA-256 over three chunks (64 + 64 + remainder): the multi-block
// acceptance shape for inputs past the old 64-byte wall.
fn candidate_sha256_blocks(a: [byte; up_to 64], la: u64, b: [byte; up_to 64], lb: u64, c: [byte; up_to 64], lc: u64, k: [u32; 64]) -> (result: [byte; 32]) {
    let s0: DigestState = init();
    let s1: DigestState = update(s0, a, la, k);
    let s2: DigestState = update(s1, b, lb, k);
    let s3: DigestState = update(s2, c, lc, k);
    return finalize(s3, k);
}

