// mncs.std.text_scan — bounded literal text scanning over byte views.
//
// Machine-native text is explicitly bounded byte views, not heap strings:
// hosts encode text as `[byte; up_to 64]` values (the executor ABI carries
// byte sequences directly) and this module decides over them with total,
// allocation-free operations. There is deliberately no regex engine here:
// the harness routing surfaces that motivated this module (literal-term
// detection, code-fence detection, file-like token detection, bounded
// word/token scanning) are all deterministic bounded scans.
//
// UTF-8 policy: operations are byte-oriented and never assume scalar
// boundaries. Validity is producer-attested (`TextView.utf8_valid`), not
// re-derived. ASCII-class decisions (`count_words`) reuse the byte-domain
// predicates from `mncs.core.bytes.v1`, never restated code points.
//
// Complexity bounds (H, N <= 64 by MAX_SEQUENCE_BOUND):
//   window_equal / starts_with / ends_with   <= N byte comparisons
//   contains / find                          <= 64*N + 64 byte comparisons
//   compare                                  <= max(N, M) byte comparisons
//   count_byte / count_words                 <= 64 steps
// No operation allocates; every function is total over its declared domain.
// An empty needle matches at every position of a non-empty view
// (contains/starts_with/ends_with are true, find returns 0); on an empty
// view contains is false and find is -1, since there is no position to
// match at.
//
// This module extends the RFC 0044 bounded-sequence-byte-view substrate
// alongside `mncs.std.text_view.v1` (spans/flags, 16/32-byte key matching)
// and `mncs.std.text_map.v1` (byte-spelling to code tables). Those keep
// their shape; this module owns multi-byte literal needles over views.
module mncs.std.text_scan.v1;

use mncs.core.bytes.v1 as bytes;
use mncs.core.logic.v1 as logic;

// Window equality: the N-byte needle matches the haystack at `start`.
// Guards keep the verdict inside both declared lengths, and every
// projection is clamped into the view's runtime length, so the operation
// is total even for overlong or misaligned inputs. The clamp matters
// because selection is strict: both `select` candidates evaluate, so a
// guarded-away projection would still trap on an out-of-bounds index.
fn window_equal<N: Nat>(hay: [byte; up_to 64], hay_length: u64, start: u64, needle: [byte; N], needle_length: u64) -> (result: bool) {
    if hay.len == 0 {
        return needle_length == 0;
    }
    let hlen: u64 = select(hay_length <= hay.len, hay_length, hay.len);
    let fits: bool = needle_length <= needle.len && start +% needle_length <= hlen;
    iterate j over needle carrying same: bool = fits {
        let k: u64 = start +% j;
        let live: bool = j < needle_length && k < hlen;
        let slot: u64 = select(k < hlen, k, 0);
        next same = same && select(live, hay[slot] == needle[j], true);
    }
    return same;
}

// Literal-term detection: the needle occurs anywhere in the view.
fn contains<N: Nat>(hay: [byte; up_to 64], hay_length: u64, needle: [byte; N], needle_length: u64) -> (result: bool) {
    iterate i over hay carrying found: bool = false {
        next found = found || window_equal<N>(hay, hay_length, i, needle, needle_length);
    }
    return found;
}

// Bounded prefix check.
fn starts_with<N: Nat>(hay: [byte; up_to 64], hay_length: u64, needle: [byte; N], needle_length: u64) -> (result: bool) {
    return window_equal<N>(hay, hay_length, 0, needle, needle_length);
}

// Bounded suffix check. The start is computed with wrapping subtraction,
// but the `fits` guard inside `window_equal` keeps the result total: an
// overlong needle simply cannot fit and reports false.
fn ends_with<N: Nat>(hay: [byte; up_to 64], hay_length: u64, needle: [byte; N], needle_length: u64) -> (result: bool) {
    let fits: bool = needle_length <= hay_length;
    let start: u64 = hay_length -% needle_length;
    return select(fits, window_equal<N>(hay, hay_length, start, needle, needle_length), false);
}

// Exact view equality over explicit lengths: true when both declared
// lengths agree and every live byte matches. Total like `window_equal`:
// lengths clamp into their declared bounds, and strict selection keeps
// every projection inside the view's runtime length. This is the
// variable-length token matcher: one entrypoint decides tokens of
// differing runtime widths (3-byte `x86` and 7-byte `aarch64` alike)
// through their explicit lengths, not through exact-width parameters.
fn equals<N: Nat>(value: [byte; up_to 64], value_length: u64, target: [byte; N], target_length: u64) -> (result: bool) {
    if value.len == 0 {
        return target_length == 0;
    }
    let vlen: u64 = select(value_length <= value.len, value_length, value.len);
    let valid: bool = vlen == target_length && target_length <= target.len;
    iterate j over target carrying same: bool = valid {
        let live: bool = j < target_length && j < vlen;
        let slot: u64 = select(j < vlen, j, 0);
        next same = same && select(live, value[slot] == target[j], true);
    }
    return same;
}

// ASCII case-insensitive exact match: the `equals` shape with bytes
// compared through `bytes.eq_ascii_fold`. Locale-free by construction:
// only the 26 ASCII pairs fold, every other byte must match exactly.
fn equals_folded<N: Nat>(value: [byte; up_to 64], value_length: u64, target: [byte; N], target_length: u64) -> (result: bool) {
    if value.len == 0 {
        return target_length == 0;
    }
    let vlen: u64 = select(value_length <= value.len, value_length, value.len);
    let valid: bool = vlen == target_length && target_length <= target.len;
    iterate j over target carrying same: bool = valid {
        let live: bool = j < target_length && j < vlen;
        let slot: u64 = select(j < vlen, j, 0);
        next same = same && select(live, bytes.eq_ascii_fold(value[slot], target[j]), true);
    }
    return same;
}

// First occurrence index as i64, or -1 when the needle is absent. The
// sentinel stays inside the i64 vocabulary; -1 can never be a valid index.
fn find<N: Nat>(hay: [byte; up_to 64], hay_length: u64, needle: [byte; N], needle_length: u64) -> (result: i64) {
    iterate i over hay carrying found: i64 = 0 - 1 {
        let hit: bool = window_equal<N>(hay, hay_length, i, needle, needle_length);
        next found = select(found == 0 - 1 && hit, i as i64, found);
    }
    return found;
}

// Deterministic byte-lexicographic ordering over explicit lengths: -1 when
// the left view sorts first, 1 when it sorts last, 0 when equal. Lengths
// are clamped to their declared bounds, then decide ties after the common
// prefix compares equal. No locale, no case folding, no Unicode collation.
record Cmp { ord: i64, decided: bool }

fn compare<N: Nat, M: Nat>(left: [byte; N], left_length: u64, right: [byte; M], right_length: u64) -> (result: i64) {
    let llen: u64 = select(left_length <= left.len, left_length, left.len);
    let rlen: u64 = select(right_length <= right.len, right_length, right.len);
    let tie: i64 = select(llen == rlen, 0, select(llen <= rlen, 0 - 1, 1));
    if right.len == 0 {
        return tie;
    }
    let seed: Cmp = Cmp { ord: 0, decided: false };
    iterate i over left carrying st: Cmp = seed {
        let live: bool = i < llen && i < rlen;
        // Strict selection evaluates both candidates, so the right-hand
        // projection is clamped into range even where `live` is false.
        let slot: u64 = select(i < rlen, i, 0);
        let diff: bool = left[i] != right[slot];
        let less: bool = left[i] <= right[slot];
        next st = Cmp {
            ord: select(logic.bool_not(st.decided) && live && diff, select(less, 0 - 1, 1), st.ord),
            decided: st.decided || (live && diff)
        };
    }
    return select(st.decided, st.ord, tie);
}

// Count occurrences of one byte in the view window.
fn count_byte(hay: [byte; up_to 64], hay_length: u64, target: byte) -> (result: u64) {
    iterate i over hay carrying hits: u64 = 0 {
        let live: bool = i < hay_length;
        next hits = hits +% select(live && hay[i] == target, 1, 0);
    }
    return hits;
}

// Bounded word scan: maximal runs of non-ASCII-space bytes. Word
// boundaries reuse the byte-domain classifier, so tokenization policy is
// one shared predicate, not per-callsite folklore.
record WordScan { count: u64, in_word: bool }

fn count_words(hay: [byte; up_to 64], hay_length: u64) -> (result: u64) {
    let seed: WordScan = WordScan { count: 0, in_word: false };
    iterate i over hay carrying st: WordScan = seed {
        let live: bool = i < hay_length;
        let word_byte: bool = live && logic.bool_not(bytes.is_ascii_space(hay[i]));
        next st = WordScan {
            count: st.count +% select(logic.bool_not(st.in_word) && word_byte, 1, 0),
            in_word: word_byte
        };
    }
    return st.count;
}

// Executable entry points with concrete shapes for backend corpora.

fn candidate_contains(hay: [byte; up_to 64], hay_length: u64, needle: [byte; 4], needle_length: u64) -> (result: bool) {
    return contains<4>(hay, hay_length, needle, needle_length);
}

fn candidate_starts_with(hay: [byte; up_to 64], hay_length: u64, needle: [byte; 4], needle_length: u64) -> (result: bool) {
    return starts_with<4>(hay, hay_length, needle, needle_length);
}

fn candidate_ends_with(hay: [byte; up_to 64], hay_length: u64, needle: [byte; 4], needle_length: u64) -> (result: bool) {
    return ends_with<4>(hay, hay_length, needle, needle_length);
}

fn candidate_find(hay: [byte; up_to 64], hay_length: u64, needle: [byte; 4], needle_length: u64) -> (result: i64) {
    return find<4>(hay, hay_length, needle, needle_length);
}

fn candidate_compare(left: [byte; 8], left_length: u64, right: [byte; 8], right_length: u64) -> (result: i64) {
    return compare<8, 8>(left, left_length, right, right_length);
}

fn candidate_count_byte(hay: [byte; up_to 64], hay_length: u64, target: byte) -> (result: u64) {
    return count_byte(hay, hay_length, target);
}

fn candidate_count_words(hay: [byte; up_to 64], hay_length: u64) -> (result: u64) {
    return count_words(hay, hay_length);
}

fn candidate_equals(value: [byte; up_to 64], value_length: u64, target: [byte; 4], target_length: u64) -> (result: bool) {
    return equals<4>(value, value_length, target, target_length);
}

fn candidate_equals_folded(value: [byte; up_to 64], value_length: u64, target: [byte; 4], target_length: u64) -> (result: bool) {
    return equals_folded<4>(value, value_length, target, target_length);
}

mncs 0.13;

// mncs.std.text_utf8 — bounded UTF-8 validation, scalar stepping, and a
// deliberately small case fold over byte views.
//
// INGEST-P-003: `text_view`/`text_scan` trade in producer-attested validity
// flags, while `json_cursor` performs real lead/continuation validation
// internally. This module is the coherent reusable substrate extracted
// from that in-tree material: it imports the three lead/continuation
// predicates from `mncs.std.json_cursor.v1` (no second decoder) and layers
// the total bounded operations ingest needs on top.
//
// Scope discipline (explicit non-goals):
// - validation reports the first bad byte index (`-1` = valid); it never
//   repairs, skips, or normalizes;
// - the scalar step decodes one scalar with a progress guarantee
//   (`next = at + 1` on malformed input, `next = at` past the window) but
//   performs no normalization (no NFC/NFD, no grapheme logic);
// - `fold_scalar` covers ASCII A-Z plus Latin-1 capitals U+00C0-U+00DE
//   except U+00D7 (multiplication sign, caseless). It is NOT full Unicode
//   case folding: no multi-scalar mappings (German ß stays ß, it never
//   becomes "SS"), no context sensitivity (Greek sigma), no Turkic
//   dotless-I, nothing above U+00DE. Anything outside the covered pairs is
//   identity, loudly documented here rather than silently approximated.
//
// Corpus: examples/execution/text-utf8-corpus.json (kept next to the
// module's candidates, following the `text_scan`/`text_map` convention).
module mncs.std.text_utf8.v1;

use mncs.std.json_cursor.v1;

// One decoded scalar: the scalar value, the position after it, and whether
// position `at` started a well-formed scalar inside the live window.
record ScalarStep { scalar: u32, next: u64, valid: bool }

// Fold state for window validation: outstanding continuation bytes, the
// lead awaiting its range-checked first continuation (`0` = none), and the
// first bad byte index (`-1` = clean so far).
record ValidateState { remaining: u64, lead: byte, error: i64 }

// Keep the first recorded error index; later lanes must not overwrite it.
fn first_error(current: i64, index: u64) -> (result: i64) {
    return select(current == 0 - 1, index as i64, current);
}

// One validation lane: total over every byte value. Dead lanes (past the
// live window) return the state unchanged, so narrowing the window never
// corrupts the verdict.
fn validate_step(state: ValidateState, value: byte, index: u64, live: bool) -> (result: ValidateState) {
    if !live {
        return state;
    }
    if state.remaining > 0 {
        if !is_utf8_continuation(value) {
            return ValidateState { remaining: 0, lead: 0, error: first_error(state.error, index) };
        }
        if state.lead != 0 {
            if !utf8_first_continuation_valid(state.lead, value) {
                return ValidateState { remaining: 0, lead: 0, error: first_error(state.error, index) };
            }
        }
        return ValidateState { remaining: state.remaining - 1, lead: 0, error: state.error };
    }
    let need: u64 = utf8_lead_need(value) as u64;
    if (value as i64) >= 128 && need == 0 {
        return ValidateState { remaining: 0, lead: 0, error: first_error(state.error, index) };
    }
    if need == 0 {
        return state;
    }
    return ValidateState { remaining: need, lead: value, error: state.error };
}

// Validate the live window `min(view_length, view.len)`: `-1` when every
// live byte forms complete well-formed UTF-8 sequences, otherwise the byte
// index of the first stray continuation, impossible lead, range-violating
// first continuation, or truncated tail. The empty window is valid.
fn validate_generic<N: Nat>(view: [byte; up_to N], view_length: u64) -> (result: i64) {
    let window: u64 = select(view_length <= view.len, view_length, view.len);
    iterate i over view carrying state: ValidateState = ValidateState { remaining: 0, lead: 0, error: 0 - 1 } {
        next state = validate_step(state, view[i], i, i < window);
    }
    if state.error != 0 - 1 {
        return state.error;
    }
    if state.remaining != 0 {
        return window as i64;
    }
    return 0 - 1;
}

// Decode the scalar starting at `at`: ASCII passes through, 2-/3-/4-byte
// leads decode through the same range table the validator uses (overlongs,
// surrogates, and >U+10FFFF fail closed). Malformed input yields
// `valid = false` with `next = at + 1` so callers always make progress;
// `at` past the window yields `valid = false` with `next = at`.
fn step_scalar_generic<N: Nat>(view: [byte; up_to N], view_length: u64, at: u64) -> (result: ScalarStep) {
    let window: u64 = select(view_length <= view.len, view_length, view.len);
    if at >= window {
        return ScalarStep { scalar: 0, next: at, valid: false };
    }
    let b0: u64 = view[at] as u64;
    if b0 < 128 {
        return ScalarStep { scalar: b0 as u32, next: at + 1, valid: true };
    }
    let need: u64 = utf8_lead_need(view[at]) as u64;
    if need == 0 {
        return ScalarStep { scalar: 0, next: at + 1, valid: false };
    }
    if need == 1 {
        if at + 1 >= window {
            return ScalarStep { scalar: 0, next: at + 1, valid: false };
        }
        let b1: u64 = view[at + 1] as u64;
        if !utf8_first_continuation_valid(view[at], view[at + 1]) {
            return ScalarStep { scalar: 0, next: at + 1, valid: false };
        }
        let scalar: u64 = (b0 - 192) * 64 + b1 % 64;
        return ScalarStep { scalar: scalar as u32, next: at + 2, valid: true };
    }
    if need == 2 {
        if at + 2 >= window {
            return ScalarStep { scalar: 0, next: at + 1, valid: false };
        }
        if !utf8_first_continuation_valid(view[at], view[at + 1]) {
            return ScalarStep { scalar: 0, next: at + 1, valid: false };
        }
        let b1: u64 = view[at + 1] as u64;
        let b2: u64 = view[at + 2] as u64;
        if !is_utf8_continuation(view[at + 2]) {
            return ScalarStep { scalar: 0, next: at + 1, valid: false };
        }
        let scalar: u64 = (b0 - 224) * 4096 + (b1 % 64) * 64 + b2 % 64;
        return ScalarStep { scalar: scalar as u32, next: at + 3, valid: true };
    }
    if at + 3 >= window {
        return ScalarStep { scalar: 0, next: at + 1, valid: false };
    }
    if !utf8_first_continuation_valid(view[at], view[at + 1]) {
        return ScalarStep { scalar: 0, next: at + 1, valid: false };
    }
    let c1: u64 = view[at + 1] as u64;
    let c2: u64 = view[at + 2] as u64;
    let c3: u64 = view[at + 3] as u64;
    if !is_utf8_continuation(view[at + 2]) {
        return ScalarStep { scalar: 0, next: at + 1, valid: false };
    }
    if !is_utf8_continuation(view[at + 3]) {
        return ScalarStep { scalar: 0, next: at + 1, valid: false };
    }
    let wide: u64 = (b0 - 240) * 262144 + (c1 % 64) * 4096 + (c2 % 64) * 64 + c3 % 64;
    return ScalarStep { scalar: wide as u32, next: at + 4, valid: true };
}

// Deliberately bounded case fold over one scalar: ASCII A-Z gains 0x20,
// Latin-1 capitals U+00C0-U+00D6 and U+00D8-U+00DE gain 0x20. Everything
// else is identity — including U+00D7 (multiplication sign, caseless),
// U+00DF (ß, whose uppercase is two scalars), all already-lowercase
// scalars, and every scalar above U+00DE. See the module header: this
// demonstrates the fold shape, it is not Unicode case folding.
fn fold_scalar(scalar: u32) -> (result: u32) {
    let n: u64 = scalar as u64;
    if n >= 65 && n <= 90 {
        return (n + 32) as u32;
    }
    if n >= 192 && n <= 214 {
        return (n + 32) as u32;
    }
    if n >= 216 && n <= 222 {
        return (n + 32) as u32;
    }
    return scalar;
}

// --- Executable entry points (scalar shapes for backend corpora) ---
//
// Corpus buffers carry content, not padding; expectations are computed
// from the corpus bytes (see examples/execution/text-utf8-corpus.json).

// Validate a staged window: packs valid-flag * 100000 + first-error rank.
// The corpus pins ASCII-valid, the `[0xC3, 0x28]` rejection at index 1,
// a stray continuation at 0, an overlong at 0, a surrogate at 1, a
// truncated tail at the window end, and the empty window as valid.
fn candidate_validate(buf: [byte; 16], view_length: u64) -> (result: i64) {
    let view: [byte; up_to 16] = buf[0..view_length];
    let error: i64 = validate_generic<16>(view, view_length);
    return select(error == 0 - 1, 100000, error);
}

// Step one scalar at `at`: packs valid * 100000000 + scalar * 100 + next.
fn candidate_step(buf: [byte; 16], view_length: u64, at: u64) -> (result: i64) {
    let view: [byte; up_to 16] = buf[0..view_length];
    let step: ScalarStep = step_scalar_generic<16>(view, view_length, at);
    return select(step.valid, 100000000, 0) + (step.scalar as i64) * 100 + step.next as i64;
}

// Fold the demonstration pairs: ASCII `A`->`a`, `É`->`é`, and the
// caseless guards (`×`, `ß`, already-lower `é`) as identity. Packs the
// five results base-100000 in order.
fn candidate_fold() -> (result: i64) {
    let a: i64 = (fold_scalar(65) as u64) as i64;
    let e: i64 = (fold_scalar(201) as u64) as i64;
    let mul: i64 = (fold_scalar(215) as u64) as i64;
    let sharp: i64 = (fold_scalar(223) as u64) as i64;
    let small: i64 = (fold_scalar(233) as u64) as i64;
    return a * 10000000000000000 + e * 100000000000 + mul * 1000000 + sharp * 1000 + small;
}

mncs 0.10;

// mncs.std.text_view — bounded, host-neutral text references.
//
// A TextView is a borrowed span into an explicitly supplied byte stream. It
// does not imply ownership, allocation, or a particular host string type. The
// producer records whether the span contains JSON escape sequences and whether
// the UTF-8 boundary checks completed. A host may decode a valid unescaped
// span directly, or hand an encoded span to a JSON-string decoder.
module mncs.std.text_view.v1;

record TextView {
    start: u64,
    length: u64,
    encoded: bool,
    utf8_valid: bool
}

fn empty() -> (result: TextView) {
    return TextView { start: 0, length: 0, encoded: false, utf8_valid: true };
}

fn span(start: u64, length: u64, encoded: bool, utf8_valid: bool) -> (result: TextView) {
    return TextView { start: start, length: length, encoded: encoded, utf8_valid: utf8_valid };
}

fn end(view: TextView) -> (result: u64) {
    return view.start +% view.length;
}

fn is_empty(view: TextView) -> (result: bool) {
    return view.length == 0;
}

fn is_decodable(view: TextView) -> (result: bool) {
    return view.utf8_valid;
}

// Bounded ASCII/key matching is deliberately generic. Callers provide the
// target bytes and length; the library does not own a schema or a field name.
fn matches16(value: [byte; 16], value_length: u64, target: [byte; 16], target_length: u64) -> (result: bool) {
    let valid_length: bool = value_length == target_length && value_length <= 16;
    iterate i over value carrying same: bool = valid_length {
        let in_target: bool = i < target_length;
        let equal: bool = value[i] == target[i];
        next same = same && select(in_target, equal, true);
    }
    return same;
}

// The wider matcher keeps schema consumers from having to classify a known
// field as unknown merely because its UTF-8 spelling is longer than 16 bytes.
// It remains bounded and allocation-free; callers still provide the target.
fn matches32(value: [byte; 32], value_length: u64, target: [byte; 32], target_length: u64) -> (result: bool) {
    let valid_length: bool = value_length == target_length && value_length <= 32;
    iterate i over value carrying same: bool = valid_length {
        let in_target: bool = i < target_length;
        let equal: bool = value[i] == target[i];
        next same = same && select(in_target, equal, true);
    }
    return same;
}

mncs 0.13;

// mncs.std.token_set — deterministic bounded token-set algebra.
//
// A token set is storage plus a logical count: `[byte; N]` holding `count`
// live entries (`count <= N`). Tokens are small host-assigned codes
// (0..=255); hosts map spellings to codes at the capability boundary, so
// classification policy stays byte-exact and allocation-free. There is no
// first-class set/map syntax and no unbounded allocation: every operation
// is a total bounded fold, overflow is an explicit verdict (never silent
// truncation), and ties always resolve to the lowest index.
//
// Complexity bounds (N, M <= 64 by MAX_SEQUENCE_BOUND):
//   contains / first_free_or_duplicate  <= N byte comparisons
//   require_all / forbid_any / prefer_hits / dedup_count  <= N*M steps
//   top_index                             <= N comparisons
// No operation allocates; every function is total over its declared domain.
module mncs.std.token_set.v1;

use mncs.core.logic.v1 as logic;

// Membership: the token occupies a live slot.
fn contains<N: Nat>(set: [byte; N], count: u64, token: byte) -> (result: bool) {
    iterate i over set carrying found: bool = false {
        let live: bool = i < count;
        next found = found || (live && set[i] == token);
    }
    return found;
}

// Insertion decision without mutation: the index where `token` already
// lives, else the first free slot (`count` when `count < N`), else -1 when
// the storage is full. Callers apply `replace` plus a count bump on
// non-negative results; a full set stays an explicit verdict, so unique
// insertion/deduplication never silently drops a token.
fn first_free_or_duplicate<N: Nat>(set: [byte; N], count: u64, token: byte) -> (result: i64) {
    let full: bool = count >= set.len;
    iterate i over set carrying slot: i64 = 0 - 1 {
        let live: bool = i < count;
        let hit: bool = live && set[i] == token;
        let free: bool = logic.bool_not(full) && i == count;
        next slot = select(slot == 0 - 1 && (hit || free), i as i64, slot);
    }
    return slot;
}

// Intersection predicate: every needed token is present.
fn require_all<N: Nat, M: Nat>(have: [byte; N], have_count: u64, need: [byte; M], need_count: u64) -> (result: bool) {
    iterate j over need carrying ok: bool = true {
        let live: bool = j < need_count;
        next ok = ok && select(live, contains<N>(have, have_count, need[j]), true);
    }
    return ok;
}

// Exclusion predicate: no banned token is present.
fn forbid_any<N: Nat, M: Nat>(have: [byte; N], have_count: u64, banned: [byte; M], banned_count: u64) -> (result: bool) {
    iterate j over banned carrying ok: bool = true {
        let live: bool = j < banned_count;
        next ok = ok && select(live, logic.bool_not(contains<N>(have, have_count, banned[j])), true);
    }
    return ok;
}

// Preference-hit counting: how many preferred tokens are present. Bounded
// aggregation over the preference domain, not over the candidate domain.
fn prefer_hits<N: Nat, M: Nat>(have: [byte; N], have_count: u64, prefer: [byte; M], prefer_count: u64) -> (result: u64) {
    iterate j over prefer carrying hits: u64 = 0 {
        let live: bool = j < prefer_count;
        next hits = hits +% select(live && contains<N>(have, have_count, prefer[j]), 1, 0);
    }
    return hits;
}

// Distinct-token count over the logical window: read-only deduplication
// semantics. Token `tokens[i]` is new when no earlier live slot holds it.
fn dedup_count<N: Nat>(tokens: [byte; N], count: u64) -> (result: u64) {
    iterate i over tokens carrying distinct: u64 = 0 {
        let live: bool = i < count;
        next distinct = distinct +% select(live && is_first_occurrence<N>(tokens, count, i), 1, 0);
    }
    return distinct;
}

fn is_first_occurrence<N: Nat>(tokens: [byte; N], count: u64, at: u64) -> (result: bool) {
    iterate k over tokens carrying seen: bool = false {
        next seen = seen || (k < at && k < count && tokens[k] == tokens[at]);
    }
    return logic.bool_not(seen);
}

// Deterministic ranking state: the incumbent maximum index plus whether
// any live score has been observed. The index defaults to 0, which is a
// valid projection whenever the storage is non-empty; strict boolean
// evaluation therefore never projects out of bounds, and no cross-type
// conversion of a negative sentinel ever evaluates.
record Top { index: u64, has: bool }

// Deterministic ranking: index of the maximum score over the logical
// window, or -1 when empty. Ties resolve to the lowest index, so ranking
// is a total function of the scores with no ambient tie-break. Scores pair
// with an external identity order (parallel id views compared with
// `text_scan.compare` where lexicographic ids must decide residual ties).
fn top_index<N: Nat>(scores: [u64; N], count: u64) -> (result: i64) {
    let seed: Top = Top { index: 0, has: false };
    iterate i over scores carrying st: Top = seed {
        let live: bool = i < count;
        let better: bool = live && (logic.bool_not(st.has) || scores[i] > scores[st.index]);
        next st = Top {
            index: select(better, i, st.index),
            has: st.has || live
        };
    }
    return select(st.has, st.index as i64, 0 - 1);
}

// Executable entry points with concrete shapes for backend corpora.

fn candidate_contains(set: [byte; 8], count: u64, token: byte) -> (result: bool) {
    return contains<8>(set, count, token);
}

fn candidate_require_all(have: [byte; 8], have_count: u64, need: [byte; 4], need_count: u64) -> (result: bool) {
    return require_all<8, 4>(have, have_count, need, need_count);
}

fn candidate_forbid_any(have: [byte; 8], have_count: u64, banned: [byte; 4], banned_count: u64) -> (result: bool) {
    return forbid_any<8, 4>(have, have_count, banned, banned_count);
}

fn candidate_prefer_hits(have: [byte; 8], have_count: u64, prefer: [byte; 4], prefer_count: u64) -> (result: u64) {
    return prefer_hits<8, 4>(have, have_count, prefer, prefer_count);
}

fn candidate_dedup_count(tokens: [byte; 8], count: u64) -> (result: u64) {
    return dedup_count<8>(tokens, count);
}

fn candidate_first_free(set: [byte; 4], count: u64, token: byte) -> (result: i64) {
    return first_free_or_duplicate<4>(set, count, token);
}

fn candidate_top_index(scores: [u64; 8], count: u64) -> (result: i64) {
    return top_index<8>(scores, count);
}
